-- One list entry: title / meta on the left, actions on the right.
-- One list entry: title over meta on the left, actions on the right.
--
-- Explicit positions, no inner layout. This used to be a horizontal list
-- holding a frame that held a vertical list, and nested auto-layout has now
-- mangled two different things in this GUI (the HUD came apart, row labels were
-- pushed off screen). Two labels and a row of icons do not need a layout engine
-- to place them.
local function listEntry(parent, title, meta, order, actionCount, height, accent)
    local n = actionCount or 2
    local actionsWidth = n * 24 + math.max(n - 1, 0) * 2
    local h = height or 46

    local e = Instance.new("Frame")
    e.Name = "Entry"
    e.BackgroundColor3 = Theme.SurfaceElement
    e.BorderSizePixel = 0
    e.Size = UDim2.new(1, 0, 0, h)
    e.LayoutOrder = order or 1
    e.ClipsDescendants = true
    e.Parent = parent
    corner(e, Theme.RadiusSm)
    stroke(e, Theme.Hairline, 1)

    -- With an accent, a colour bar runs down the left edge and the text moves
    -- over to make room; this is how a list entry says "the cyan one".
    local textX = 10
    if accent then
        local bar = Instance.new("Frame")
        bar.Name = "Accent"
        bar.BackgroundColor3 = accent
        bar.BorderSizePixel = 0
        bar.Size = UDim2.new(0, 5, 1, 0)
        bar.Parent = e
        textX = 16
    end
    local textWidth = -(textX + actionsWidth + 16)

    local titleLabel = label(e, title, "rowEntry", 1)
    titleLabel.Position = UDim2.fromOffset(textX, 5)
    titleLabel.Size = UDim2.new(1, textWidth, 0, 17)
    titleLabel.TextTruncate = Enum.TextTruncate.AtEnd

    local metaLabel = label(e, meta or "", "monoMeta", 2)
    metaLabel.Position = UDim2.fromOffset(textX, 24)
    metaLabel.Size = UDim2.new(1, textWidth, 0, 14)
    metaLabel.TextTruncate = Enum.TextTruncate.AtEnd

    local actions = Instance.new("Frame")
    actions.Name = "Actions"
    actions.BackgroundTransparency = 1
    actions.AnchorPoint = Vector2.new(1, 0.5)
    actions.Position = UDim2.new(1, -8, 0.5, 0)
    actions.Size = UDim2.fromOffset(actionsWidth, 24)
    actions.Parent = e
    hlist(actions, 2)

    return { frame = e, title = titleLabel, meta = metaLabel, actions = actions }
end

-- Row action icons, drawn from rectangles: no asset to fail to load.
local function iconButton(parent, kind, onClick, order, explain)
    local b = Instance.new("TextButton")
    b.Name = kind
    b.BackgroundColor3 = Theme.SurfaceHover
    b.BackgroundTransparency = 1
    b.BorderSizePixel = 0
    b.Size = UDim2.fromOffset(24, 24)
    b.Text = ""
    b.AutoButtonColor = false
    b.LayoutOrder = order or 1
    b.Parent = parent
    corner(b, Theme.RadiusSm)
    b.MouseEnter:Connect(function() b.BackgroundTransparency = 0.7 end)
    b.MouseLeave:Connect(function() b.BackgroundTransparency = 1 end)

    local function piece(color, w, h, x, y, angle, radius)
        local f = Instance.new("Frame")
        f.BackgroundColor3 = color
        f.BorderSizePixel = 0
        f.AnchorPoint = Vector2.new(0.5, 0.5)
        f.Size = UDim2.fromOffset(w, h)
        f.Position = UDim2.fromOffset(x, y)
        f.Rotation = angle or 0
        f.ZIndex = 2
        if radius then corner(f, radius) end
        f.Parent = b
        return f
    end

    if kind == "edit" then
        piece(Theme.AccentMid, 3, 12, 13, 11, 45, 1)
        piece(Theme.AccentMid, 3, 3, 8, 17, 45)
    elseif kind == "delete" then
        piece(Theme.StatusBad, 11, 2, 12, 7, 0, 1)
        piece(Theme.StatusBad, 9, 9, 12, 14, 0, 2)
    elseif kind == "up" then
        piece(Theme.TextSub, 7, 2, 10, 13, 45, 1)
        piece(Theme.TextSub, 7, 2, 14, 13, -45, 1)
    elseif kind == "down" then
        piece(Theme.TextSub, 7, 2, 10, 11, -45, 1)
        piece(Theme.TextSub, 7, 2, 14, 11, 45, 1)
    elseif kind == "play" then
        piece(Theme.StatusGood, 3, 10, 10, 12, 0, 1)
        piece(Theme.StatusGood, 3, 10, 14, 12, 0, 1)
    elseif kind == "check" then
        piece(Theme.StatusGood, 3, 7, 9, 14, -45, 1)
        piece(Theme.StatusGood, 3, 13, 14, 11, 45, 1)
    elseif kind == "cross" then
        piece(Theme.StatusBad, 3, 14, 12, 12, 45, 1)
        piece(Theme.StatusBad, 3, 14, 12, 12, -45, 1)
    end

    if onClick then b.MouseButton1Click:Connect(onClick) end
    tip(b, explain)
    return b
end

-- =========================================================================
-- Window and section
-- =========================================================================

local function makeDraggable(handle, target)
    local dragging, startPos, startOffset = false, nil, nil
    handle.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1
            or input.UserInputType == Enum.UserInputType.Touch then
            dragging = true
            startPos = input.Position
            startOffset = target.Position
        end
    end)
    handle.InputEnded:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1
            or input.UserInputType == Enum.UserInputType.Touch then
            dragging = false
        end
    end)
    table.insert(S.sliderConnections, UserInputService.InputChanged:Connect(function(input)
        if not dragging then return end
        if input.UserInputType ~= Enum.UserInputType.MouseMovement
            and input.UserInputType ~= Enum.UserInputType.Touch then return end
        local delta = input.Position - startPos
        target.Position = UDim2.new(
            startOffset.X.Scale, startOffset.X.Offset + delta.X,
            startOffset.Y.Scale, startOffset.Y.Offset + delta.Y)
    end))
end

-- A window: accent bar, header (drag handle, accent tile, title, optional ⓘ),
-- hairline divider, then a scrolling body. The body scrolls because a full
-- accordion is taller than a 768p screen, which is the one thing a fixed
-- height would get wrong on half the machines this runs on.
local function window(parent, opts)
    local frame = Instance.new("Frame")
    frame.Name = opts.name or "Window"
    frame.BackgroundColor3 = Color3.new(1, 1, 1)
    frame.BorderSizePixel = 0
    frame.Size = UDim2.fromOffset(opts.width or 310, opts.height or 460)
    frame.Position = opts.position or UDim2.fromOffset(40, 40)
    frame.Visible = opts.visible ~= false
    frame.Active = true
    frame.ClipsDescendants = true
    frame.ZIndex = 2
    frame.Parent = parent
    corner(frame, Theme.RadiusLg)
    stroke(frame, Theme.Hairline, 1)
    bodyGradient(frame)
    shadow(frame)

    local accent = Instance.new("Frame")
    accent.Name = "AccentBar"
    accent.BackgroundColor3 = Color3.new(1, 1, 1)
    accent.BorderSizePixel = 0
    accent.Size = UDim2.new(1, 0, 0, 3)
    accent.ZIndex = 3
    accent.Parent = frame
    accentGradient(accent, 0)

    local header = Instance.new("Frame")
    header.Name = "Header"
    header.BackgroundColor3 = Theme.SurfaceHeader
    header.BorderSizePixel = 0
    header.Size = UDim2.new(1, 0, 0, Theme.HeaderH)
    header.Position = UDim2.fromOffset(0, 3)
    header.Active = true
    header.ZIndex = 3
    header.Parent = frame
    pad(header, 0, 12, 0, 14)
    hlist(header, Theme.GapLg)
    makeDraggable(header, frame)

    local tile = Instance.new("Frame")
    tile.Name = "Icon"
    tile.BackgroundColor3 = Color3.new(1, 1, 1)
    tile.BorderSizePixel = 0
    tile.Size = UDim2.fromOffset(14, 14)
    tile.LayoutOrder = 1
    tile.ZIndex = 4
    tile.Parent = header
    corner(tile, 4)
    accentGradient(tile, 45)

    local title = label(header, opts.title or "Window", "windowTitle", 2)
    title.ZIndex = 4
    -- tile (14) + gap (12), the pin (20) + gap (12), and the info circle
    -- (20) + gap (12) when there is one.
    flexFill(title, 26 + 32 + (opts.info and 32 or 0))

    -- The pin. A pinned window stays on screen after the interface is closed,
    -- so a readout you want while you play does not cost you the whole GUI.
    -- Grey when it is not pinned, accent when it is.
    local pinned = false
    local pin = Instance.new("TextButton")
    pin.Name = "Pin"
    pin.BackgroundColor3 = Theme.SurfaceElement
    pin.BorderSizePixel = 0
    pin.Size = UDim2.fromOffset(20, 20)
    pin.Text = ""
    pin.AutoButtonColor = false
    pin.LayoutOrder = 3
    pin.ZIndex = 4
    pin.Parent = header
    corner(pin, 6)
    local pinStroke = stroke(pin, Theme.Hairline, 1)

    -- A thumbtack, drawn from two frames: no asset to fail to load.
    local pinHead = Instance.new("Frame")
    pinHead.Name = "Head"
    pinHead.BorderSizePixel = 0
    pinHead.AnchorPoint = Vector2.new(0.5, 0.5)
    pinHead.Position = UDim2.fromOffset(10, 7)
    pinHead.Size = UDim2.fromOffset(11, 4)
    pinHead.ZIndex = 5
    corner(pinHead, 2)
    pinHead.Parent = pin

    local pinStem = Instance.new("Frame")
    pinStem.Name = "Stem"
    pinStem.BorderSizePixel = 0
    pinStem.AnchorPoint = Vector2.new(0.5, 0)
    pinStem.Position = UDim2.fromOffset(10, 9)
    pinStem.Size = UDim2.fromOffset(3, 7)
    pinStem.ZIndex = 5
    corner(pinStem, 1)
    pinStem.Parent = pin

    local function renderPin()
        local color = pinned and Theme.AccentMid or Theme.TextMuted
        pinHead.BackgroundColor3 = color
        pinStem.BackgroundColor3 = color
        pinStroke.Color = pinned and Theme.AccentMid or Theme.Hairline
        pin.BackgroundColor3 = pinned and Theme.SurfaceHover or Theme.SurfaceElement
    end
    renderPin()
    tip(pin, "Pin this window so it stays on screen after you close the interface. You can still drag it. Click again to let it hide with the rest.")

    if opts.info then
        local info = Instance.new("TextLabel")
        info.Name = "Info"
        info.BackgroundColor3 = Theme.SurfaceElement
        info.BorderSizePixel = 0
        info.Size = UDim2.fromOffset(20, 20)
        info.Text = "i"
        info.TextColor3 = Theme.TextSub
        info.TextSize = 12
        info.LayoutOrder = 3
        info.ZIndex = 4
        setFont(info, "sans", Enum.FontWeight.Bold)
        info.Parent = header
        corner(info, 10)
        stroke(info, Theme.Hairline, 1)
        tip(info, opts.info)
    end

    local divider = Instance.new("Frame")
    divider.Name = "Divider"
    divider.BackgroundColor3 = Theme.Hairline
    divider.BorderSizePixel = 0
    divider.Size = UDim2.new(1, 0, 0, 1)
    divider.Position = UDim2.fromOffset(0, 3 + Theme.HeaderH)
    divider.ZIndex = 3
    divider.Parent = frame

    local body = Instance.new("ScrollingFrame")
    body.Name = "Body"
    body.BackgroundTransparency = 1
    body.BorderSizePixel = 0
    body.Position = UDim2.fromOffset(0, 4 + Theme.HeaderH)
    body.Size = UDim2.new(1, 0, 1, -(4 + Theme.HeaderH))
    body.CanvasSize = UDim2.new()
    body.AutomaticCanvasSize = Enum.AutomaticSize.Y
    body.ScrollBarThickness = 4
    body.ScrollBarImageColor3 = Color3.fromHex("50505f")
    body.ZIndex = 3
    body.Parent = frame
    pad(body, 10, Theme.GapLg, Theme.GapXl, Theme.GapLg)
    vlist(body, Theme.GapSm)

    local api = { frame = frame, header = header, body = body, title = title }

    function api.isPinned() return pinned end
    function api.setPinned(value)
        pinned = value and true or false
        renderPin()
        if opts.onPinChanged then opts.onPinChanged(api) end
    end
    pin.MouseButton1Click:Connect(function() api.setPinned(not pinned) end)

    return api
end

-- A collapsible section: the Row is the header, the content sits under it and
-- the whole thing grows with what is inside.
local function section(parent, title, order, explain)
    local holder = Instance.new("Frame")
    holder.Name = "Section"
    holder.BackgroundTransparency = 1
    holder.AutomaticSize = Enum.AutomaticSize.Y
    holder.Size = UDim2.new(1, 0, 0, 0)
    holder.LayoutOrder = order or 1
    holder.Parent = parent
    vlist(holder, Theme.GapSm)

    local head, headLabel, _ = row(holder, title, 1, nil, 24)
    head.BackgroundColor3 = Theme.SurfaceSection
    local hit = hoverable(head, true)
    local chev = chevron(head)

    -- The rows of an open section sit in a well a shade darker than the
    -- window, so the settings read as cards inside the list they belong to.
    local content = Instance.new("Frame")
    content.Name = "Content"
    content.BackgroundColor3 = Theme.SurfaceWell
    content.BorderSizePixel = 0
    content.AutomaticSize = Enum.AutomaticSize.Y
    content.Size = UDim2.new(1, 0, 0, 0)
    content.Visible = false
    content.LayoutOrder = 2
    content.Parent = holder
    corner(content, Theme.RadiusMd)
    vlist(content, Theme.GapSm)
    pad(content, 6, 6, 6, 6)

    local open = false
    local function setOpen(value)
        open = value and true or false
        content.Visible = open
        chev.setOpen(open)
        headLabel.TextColor3 = open and Theme.AccentMid or Theme.TextPrimary
    end
    setOpen(false)
    hit.onClick(function() setOpen(not open) end)
    tip(head, explain)

    return { holder = holder, content = content, setOpen = setOpen, isOpen = function() return open end }
end

-- A segmented control - the "island" at the top of a window. Exactly one of
-- the options is live, and picking one is a mode switch, not a setting: the
-- sections below it change with the choice.
local function segmented(parent, options, get, set, order, explain)
    local holder = Instance.new("Frame")
    holder.Name = "Segmented"
    holder.BackgroundColor3 = Theme.SurfaceField
    holder.BorderSizePixel = 0
    holder.Size = UDim2.new(1, 0, 0, 34)
    holder.LayoutOrder = order or 1
    holder.Parent = parent
    corner(holder, Theme.RadiusMd)
    stroke(holder, Theme.Hairline, 1)
    pad(holder, 3, 3, 3, 3)
    hlist(holder, 3)

    local buttons = {}
    local render

    for i, option in ipairs(options) do
        local b = Instance.new("TextButton")
        b.Name = tostring(option.value)
        b.BackgroundColor3 = Theme.SurfaceField
        b.BackgroundTransparency = 1
        b.BorderSizePixel = 0
        b.Size = UDim2.new(1 / #options, -(3 * (#options - 1)) / #options, 1, 0)
        b.Text = option.label or tostring(option.value)
        b.TextSize = 12
        b.AutoButtonColor = false
        b.LayoutOrder = i
        setFont(b, "sans", Enum.FontWeight.SemiBold)
        b.Parent = holder
        corner(b, Theme.RadiusSm)
        accentGradient(b, 0).Enabled = false
        buttons[option.value] = b
        tip(b, option.tip)
        b.MouseButton1Click:Connect(function()
            set(option.value)
            render()
        end)
    end

    render = function()
        local current = get()
        for value, b in pairs(buttons) do
            local on = value == current
            local grad = b:FindFirstChildOfClass("UIGradient")
            if grad then grad.Enabled = on end
            b.BackgroundTransparency = on and 0 or 1
            b.BackgroundColor3 = on and Color3.new(1, 1, 1) or Theme.SurfaceField
            b.TextColor3 = on and Theme.TextOnAccent or Theme.TextSub
        end
    end
    render()
    tip(holder, explain)
    return { holder = holder, render = render }
end

-- A plain hairline, used to fence off the master toggle at the top of a window.
local function separator(parent, order)
    local line = Instance.new("Frame")
    line.Name = "Separator"
    line.BackgroundColor3 = Theme.Hairline
    line.BorderSizePixel = 0
    line.Size = UDim2.new(1, 0, 0, 1)
    line.LayoutOrder = order or 1
    line.Parent = parent
    return line
end

-- A caption line, for the notes under a group of controls.
local function caption(parent, text, order)
    local l = label(parent, text, "captionSub", order)
    l.AutomaticSize = Enum.AutomaticSize.Y
    l.Size = UDim2.new(1, 0, 0, 0)
    l.TextWrapped = true
    l.TextYAlignment = Enum.TextYAlignment.Top
    return l
end

S.UIKit = {
    Theme = Theme,
    setFont = setFont, corner = corner, stroke = stroke, pad = pad,
    vlist = vlist, hlist = hlist, label = label, caption = caption, flexFill = flexFill,
    accentGradient = accentGradient, bodyGradient = bodyGradient, shadow = shadow,
    ensureTip = ensureTip, tip = tip, hideTip = hideTip,
    chevron = chevron, row = row, hoverable = hoverable,
    toggle = toggle, squareToggle = squareToggle, slider = slider, dropdown = dropdown, numberBox = numberBox,
    colorRow = colorRow, button = button, buttonRow = buttonRow,
    textField = textField, list = list, listEntry = listEntry, iconButton = iconButton,
    window = window, section = section, separator = separator, segmented = segmented,
    makeDraggable = makeDraggable,
}
end
    end)()
    module(S)
end

-- ===================================== src/reader.lua =====================================
do
    local module = (function()
-- reader.lua - Reads the game's attacks. Every Model with a hitBox or precast
-- under workspace is tracked from the moment it appears and its precast is
-- read every frame; every BasePart parented straight to workspace is tracked
-- as a projectile, with the boss remote event that made it when one matches;
-- the enemies are scanned from the dungeon's enemy folders; every hit is
-- written down with what enclosed the character. Nothing here learns timing
-- from being hit: the timing comes from the precast and from bosses.lua.
--
-- What the real Northern Lands capture (2026-09-02, 6 deaths, 422 attacks)
-- showed, and what this module is built on: the precast is visible from the
-- moment the Model appears, flashes to transparency 0.17 at the instant the
-- hit lands, and fades to 1.0 about 0.2 s later. The invisible hitBox stays
-- for seven seconds afterwards and never hurts again.
return function(S)
local CFG = S.CFG
local RT = S.RT
local HZ = S.HZ
local PC = S.PC
local Workspace = S.Workspace
local ReplicatedStorage = S.ReplicatedStorage
local Players = S.Players
local LocalPlayer = S.LocalPlayer
local heavyDebug = S.heavyDebug
local isKnownOwnEffect = S.isKnownOwnEffect

local V3 = Vector3.new
local clock = os.clock
local INF = math.huge
local fmt = string.format

local byInst = {}          -- [instance] = record
local candidates = {}      -- [Model] = os.clock() it appeared
local events = {}          -- recent boss projectile events, newest last
local recent = {}          -- records that ended within the last second (hit blame)
local connections = {}
local timeSync
local gameOffset = 0       -- game clock = os.clock() + gameOffset
HZ.finished = {}           -- ended records kept while a capture is recording

-- ------------------------------------------------------------------ clocks
local function syncClock()
    local ok, t = pcall(function()
        if timeSync then return timeSync:GetTime() end
        return Workspace:GetServerTimeNow()
    end)
    if ok and type(t) == "number" then gameOffset = t - clock() end
end
local function gameTime(t) return t + gameOffset end

-- ------------------------------------------------------------------ helpers
local function sz(v) return fmt("%.0fx%.0fx%.0f", v.X, v.Y, v.Z) end
local function statFor(key)
    local st = HZ.stats[key]
    if not st then
        st = { n = 0, flashN = 0, flashSum = 0, inside = {}, hits = {} }
        HZ.stats[key] = st
    end
    return st
end
local function bucket(age)
    if age > 12 then age = 12 end
    return math.floor(age / 0.25)
end
local function trace(rec, now, tr)
    if not CFG.diagnoseAttacks then return end
    rec.trace = rec.trace or {}
    local n = #rec.trace
    if n < 60 then rec.trace[n + 1] = fmt("%.2f:%.2f", now - rec.spawn, tr) end
end
local function closeSpan(rec, now)
    rec.inside = false
    rec.spans = rec.spans or {}
    if #rec.spans < 40 then rec.spans[#rec.spans + 1] = fmt("%.2f-%.2f", rec.insideAt - rec.spawn, now - rec.spawn) end
end

-- The shape a record is scored against. Cylinders and balls are discs (the
-- circle strike's precast, the jump slam's hitBox); mesh parts are discs of
-- their widest extent (the projectiles); everything else is a box.
local function shapeOf(part)
    local ok, shape = pcall(function() return part.Shape end)
    if ok and shape == Enum.PartType.Cylinder then return "disc", part.Size.Y * 0.5 end
    if ok and shape == Enum.PartType.Ball then return "disc", part.Size.X * 0.5 end
    if not ok then
        local s = part.Size
        return "disc", math.max(s.X, s.Z) * 0.5
    end
    return "box", 0
end

-- ------------------------------------------------------------------ the book
-- Every attack name the reader meets goes into this map's Attack Book, where
-- the Attacks panel shows its measured timing and lets it be switched off.
local function bookSeen(rec)
    local r = HZ.bookByName[rec.key]
    if not r then
        r = { name = rec.name, enabled = true, hits = 0, damage = 0 }
        HZ.attackBook[#HZ.attackBook + 1] = r
        HZ.bookByName[rec.key] = r
        if S.refreshAttackBookPanel then pcall(S.refreshAttackBookPanel) end
    end
    rec.disabled = r.enabled == false
end
local function invalidateAttackBook()
    HZ.bookByName = {}
    for _, r in ipairs(HZ.attackBook) do
        if type(r.name) == "string" then HZ.bookByName[string.lower(r.name)] = r end
    end
    for _, rec in ipairs(HZ.attacks) do
        local r = HZ.bookByName[rec.key]
        rec.disabled = r ~= nil and r.enabled == false
    end
end

-- ------------------------------------------------------------------ records
local function addRecord(rec)
    HZ.attacks[#HZ.attacks + 1] = rec
    if rec.inst then byInst[rec.inst] = rec end
    PC.received = PC.received + 1
    local st = statFor(rec.key)
    st.n = st.n + 1
    if rec.kind == "model" then bookSeen(rec) end
    return rec
end
local function removeRecord(rec, now)
    if rec.inside then closeSpan(rec, now) end
    rec.removed = now
    if rec.inst then byInst[rec.inst] = nil end
    for i = #HZ.attacks, 1, -1 do
        if HZ.attacks[i] == rec then table.remove(HZ.attacks, i) break end
    end
    recent[#recent + 1] = rec
    if CFG.diagnoseAttacks and rec.kind ~= "pred" then
        HZ.finished[#HZ.finished + 1] = rec
        if #HZ.finished > CFG.diagnoseMax then table.remove(HZ.finished, 1) end
    end
end

local function newModelRecord(model, spawn)
    return addRecord({
        kind = "model", inst = model, name = model.Name, key = string.lower(model.Name),
        spawn = spawn or clock(), tr = 1, visible = false,
    })
end

-- ------------------------------------------------------------------ geometry
-- Where a projectile is at time t: on its scripted path when the boss event
-- gave one, else along its measured velocity for at most the lookahead.
local function projPos(rec, t)
    local ev = rec.ev
    if ev then
        local k = (gameTime(t) - ev.start) / ev.dur
        if k < 0 then k = 0 elseif k > 1 then k = 1 end
        return ev.origin + ev.look * (k * ev.dist)
    end
    local dt = t - rec.sampledAt
    if dt > CFG.projectileLookahead then dt = CFG.projectileLookahead end
    if dt < 0 then dt = 0 end
    if not rec.vel then return rec.pos end
    return rec.pos + rec.vel * dt
end

-- Planar distance from (x, z) to the record's shape at time t; 0 or less inside.
local function attackDistance(rec, x, z, t)
    if rec.kind == "part" then
        local p = projPos(rec, t)
        local dx, dz = p.X - x, p.Z - z
        return math.sqrt(dx * dx + dz * dz) - rec.radius
    end
    local part = rec.part
    if rec.shape == "disc" then
        local c = rec.center or part.Position
        local dx, dz = c.X - x, c.Z - z
        return math.sqrt(dx * dx + dz * dz) - rec.radius
    end
    local cf = rec.cframe or part.CFrame
    local size = rec.size or part.Size
    local l = cf:PointToObjectSpace(V3(x, cf.Position.Y, z))
    local dx = math.max(math.abs(l.X) - size.X * 0.5, 0)
    local dz = math.max(math.abs(l.Z) - size.Z * 0.5, 0)
    return math.sqrt(dx * dx + dz * dz)
end

-- The interval (in os.clock seconds) during which the record can hurt, or
-- nil when it cannot. Unknown timing means the whole visible life plus a
-- linger; known timing (bosses.lua, or the flash once it is seen) means a
-- short window around the flash and floor before and after.
local function window(rec)
    local kind = rec.kind
    if kind ~= "model" then return rec.open, rec.close end
    if rec.disabled then return nil end
    local lead, after = CFG.dodgeLead, CFG.hitAfter
    if rec.flashAt then return rec.flashAt - lead, rec.flashAt + after end
    local T = rec.flashTime
    if T and not rec.pre then
        local close = rec.spawn + T + after
        if clock() > close and rec.visible then
            -- Overdue and still showing: the table is wrong for this one, so it
            -- stays live until it fires or fades.
            close = (rec.fadeAt or INF) + CFG.fadeLinger
        end
        return rec.spawn + T - lead, close
    end
    if rec.visAt then return rec.visAt, (rec.fadeAt or INF) + CFG.fadeLinger end
    return nil
end
local function attackLive(rec, t)
    local open, close = window(rec)
    return open ~= nil and t >= open and t <= close
end

-- ------------------------------------------------------------------ sampling
local function adopt(rec)
    local m = rec.inst
    if not rec.hb then
        local hb = m:FindFirstChild("hitBox")
        if hb and hb:IsA("BasePart") then rec.hb = hb end
    end
    if not rec.pc then
        local pc = m:FindFirstChild("precast")
        if pc and pc:IsA("BasePart") then rec.pc = pc end
    end
    local part = rec.hb or rec.pc
    if part and rec.part ~= part then
        rec.part = part
        rec.shape, rec.radius = shapeOf(part)
        rec.sizeText = sz(part.Size)
        rec.flashTime = S.flashTimeFor and S.flashTimeFor(rec) or nil
        if rec.flashTime then PC.total = PC.total + 1 end
        if S.onAttackShape then S.onAttackShape(rec) end
    end
end

local function sampleInside(rec, now, step, rx, rz)
    if rx == nil then return end
    local inside = attackDistance(rec, rx, rz, now) <= 0
    if inside and not rec.inside then
        rec.inside, rec.insideAt = true, now
    elseif rec.inside and not inside then
        closeSpan(rec, now)
    end
    if inside then
        local st = statFor(rec.key)
        local b = bucket(now - rec.spawn)
        st.inside[b] = (st.inside[b] or 0) + step
    end
end

local function sampleModel(rec, now, step, rx, rz)
    local m = rec.inst
    if not m.Parent then removeRecord(rec, now) return end
    adopt(rec)
    local pc = rec.pc
    if pc then
        local tr = pc.Transparency
        rec.tr = tr
        local visible = tr < 0.97
        rec.visible = visible
        if visible and not rec.visAt then rec.visAt = now end
        if visible and tr <= 0.2 and not rec.flashAt then
            rec.flashAt = now
            local st = statFor(rec.key)
            st.flashN = st.flashN + 1
            st.flashSum = st.flashSum + (now - rec.spawn)
        end
        if rec.visAt and not rec.fadeAt and not visible then rec.fadeAt = now end
        if rec.lastT == nil or math.abs(tr - rec.lastT) >= 0.02 then
            rec.lastT = tr
            trace(rec, now, tr)
        end
    end
    if CFG.diagnoseAttacks and rec.part then sampleInside(rec, now, step, rx, rz) end
    -- Over: past its window, or a plain Model that never showed anything for
    -- fifteen seconds. Parked pool Models (present before the reader) stay.
    local _, close = window(rec)
    if close and now > close + 0.5 then rec.done = true end
    if rec.done and not rec.pre then removeRecord(rec, now) end
end

local function samplePart(rec, now, step, rx, rz)
    local p = rec.inst
    if not p.Parent then removeRecord(rec, now) return end
    local pos = p.Position
    local dt = now - rec.sampledAt
    if dt > 0.05 then
        local v = (pos - rec.pos) / dt
        rec.vel = rec.vel and (rec.vel * 0.5 + v * 0.5) or v
        rec.pos, rec.sampledAt = pos, now
    end
    local tr = p.Transparency
    if rec.lastT == nil or math.abs(tr - rec.lastT) >= 0.02 then
        rec.lastT = tr
        trace(rec, now, tr)
    end
    rec.tr = tr
    if tr < 0.97 and not rec.visAt then rec.visAt = now end
    if rec.visAt and tr >= 0.97 and not rec.fadeAt then rec.fadeAt = now end
    -- Live from the event or from the moment it shows; over when the event
    -- says so or when it fades.
    if rec.ev then
        rec.open = rec.spawn
        rec.close = rec.ev.stop - gameOffset
    elseif rec.vel and rec.vel.Magnitude > CFG.projectileMaxSpeed then
        -- Faster than any projectile here: a tweened visual (the spearman's
        -- strike part crosses 65 studs in a quarter second). Floor.
        rec.open = nil
    else
        rec.open = rec.visAt
        rec.close = rec.fadeAt and (rec.fadeAt + 0.1) or INF
    end
    if CFG.diagnoseAttacks then sampleInside(rec, now, step, rx, rz) end
    if now > (rec.close or INF) + 0.5 or (not rec.visAt and now - rec.spawn > 12) then
        removeRecord(rec, now)
    end
end

local function sampleZone(rec, now)
    if not rec.part.Parent then removeRecord(rec, now) end
end

-- ------------------------------------------------------------------ workspace
local function isOwn(part)
    if HZ.ownNames[string.lower(part.Name)] then return true end
    local ok, own = pcall(isKnownOwnEffect, part)
    return ok and own == true
end

local function linkEvent(rec)
    local now = clock()
    for i = #events, 1, -1 do
        local ev = events[i]
        if now - ev.at > 0.5 then break end
        if (ev.origin - rec.pos).Magnitude <= 3 then rec.ev = ev return end
    end
end

local function onChildAdded(child)
    if RT.destroyed then return end
    if child:IsA("Model") then
        if child:FindFirstChildOfClass("Humanoid") then return end
        candidates[child] = clock()
    elseif child:IsA("BasePart") then
        if child == RT.visualRoot then return end
        local s = child.Size
        local radius = math.max(s.X, s.Y, s.Z) * 0.5
        local key = string.lower(child.Name)
        if (radius < 1.5 and not HZ.learnedNames[key]) or isOwn(child) then return end
        local now = clock()
        local rec = addRecord({
            kind = "part", inst = child, name = child.Name, key = key, spawn = now,
            pos = child.Position, sampledAt = now, radius = math.max(radius, 1), tr = child.Transparency,
            sizeText = sz(s), open = nil, close = INF,
        })
        linkEvent(rec)
    end
end

local function promoteCandidates(now)
    for model, since in pairs(candidates) do
        if not model.Parent then
            candidates[model] = nil
        elseif model:FindFirstChild("hitBox") or model:FindFirstChild("precast") then
            candidates[model] = nil
            newModelRecord(model, since)
        elseif now - since > 2 then
            candidates[model] = nil
        end
    end
end

-- ------------------------------------------------------------------ events
local function onEvent(remoteName, name, args)
    if type(args) == "table" and typeof(args[5]) == "CFrame" and type(args[1]) == "number" and type(args[3]) == "number" then
        events[#events + 1] = {
            name = tostring(name), dist = args[1], dur = args[2], start = args[3], stop = args[4],
            origin = args[5].Position, look = args[5].LookVector, at = clock(),
        }
        if #events > 64 then table.remove(events, 1) end
    end
    if S.onBossEvent then pcall(S.onBossEvent, remoteName, name, args) end
end

-- ------------------------------------------------------------------ enemies
local function scanEnemies()
    local list = {}
    local mine = LocalPlayer.Character
    local function consider(m)
        if not m:IsA("Model") or m == mine or Players:GetPlayerFromCharacter(m) then return end
        local hum = m:FindFirstChildOfClass("Humanoid")
        local root = m:FindFirstChild("HumanoidRootPart") or m.PrimaryPart
        if not hum or not root or hum.Health <= 0 then return end
        local md, st = m:FindFirstChild("meleeDistance"), m:FindFirstChild("enemyStyle")
        local style = st and tostring(st.Value) or ""
        local s = root.Size
        list[#list + 1] = {
            model = m, root = root, humanoid = hum, name = m.Name,
            melee = (md and tonumber(md.Value)) or CFG.enemyMeleeReach,
            style = style, boss = string.find(string.lower(style), "boss") ~= nil,
            extent = math.max(s.X, s.Z) * 0.5,
        }
    end
    local dungeon = Workspace:FindFirstChild("dungeon")
    if dungeon then
        for _, room in ipairs(dungeon:GetChildren()) do
            local ef = room:FindFirstChild("enemyFolder")
            if ef then for _, m in ipairs(ef:GetChildren()) do consider(m) end end
        end
    end
    local en = Workspace:FindFirstChild("enemies")
    if en then for _, m in ipairs(en:GetChildren()) do consider(m) end end
    if #list == 0 then for _, m in ipairs(Workspace:GetChildren()) do consider(m) end end
    HZ.enemies = list
    return list
end

-- ------------------------------------------------------------------ hits
local function recordHit(damage)
    local now = clock()
    local char = LocalPlayer.Character
    local root = char and char:FindFirstChild("HumanoidRootPart")
    local p = root and root.Position
    HZ.lastHitAt = now
    local best, bestScore = nil, INF
    local near = {}
    local function consider(rec)
        if not p or rec.kind == "pred" then return end
        local ok, d = pcall(attackDistance, rec, p.X, p.Z, now)
        if not ok or d > 4 then return end
        local open, close = window(rec)
        local live = open ~= nil and now >= open - 0.3 and now <= close + 0.3
        local score = (live and 0 or 10) + math.max(d, 0)
        near[#near + 1] = fmt("%s age=%.2f tr=%.2f dist=%.1f%s", rec.name, now - rec.spawn, rec.tr or 1, d, live and " LIVE" or "")
        if score < bestScore then best, bestScore = rec, score end
    end
    for _, rec in ipairs(HZ.attacks) do consider(rec) end
    for _, rec in ipairs(recent) do consider(rec) end
    local culprit = best and best.name or nil
    HZ.lastHitName = culprit
    if best then
        local st = statFor(best.key)
        local b = bucket(now - best.spawn)
        st.hits[b] = (st.hits[b] or 0) + 1
        local r = HZ.bookByName[best.key]
        if r then r.hits = (r.hits or 0) + 1 r.damage = (r.damage or 0) + (damage or 0) end
    end
    local enemies = {}
    for _, e in ipairs(HZ.enemies) do
        if p and e.root.Parent then
            local d = (e.root.Position - p).Magnitude
            if d <= 25 then enemies[#enemies + 1] = fmt("%s %.0f", e.name, d) end
        end
    end
    local stun = Workspace:FindFirstChild("stunParts")
    local stunned = stun ~= nil and stun:FindFirstChild(LocalPlayer.Name) ~= nil
    HZ.hitLog[#HZ.hitLog + 1] = fmt("HIT %s dmg=%.0f pos=%s%s culprit=%s | near: %s | enemies: %s",
        os.date("%H:%M:%S"), damage or 0, p and fmt("(%.0f,%.0f,%.0f)", p.X, p.Y, p.Z) or "?",
        stunned and " STUNNED" or "", tostring(culprit), table.concat(near, "; "), table.concat(enemies, ", "))
    if #HZ.hitLog > 80 then table.remove(HZ.hitLog, 1) end
    heavyDebug("Hit", HZ.hitLog[#HZ.hitLog])
    if S.refreshHitPanel then pcall(S.refreshHitPanel) end
end

-- ------------------------------------------------------------------ zones and predictions
local function addZoneRecord(part, shape, radius, name)
    local rec = {
        kind = "zone", inst = part, part = part, name = name or part.Name, key = string.lower(name or part.Name),
        spawn = clock(), shape = shape == "circle" and "disc" or "box", radius = radius,
        cframe = shape ~= "circle" and part.CFrame or nil,
        size = shape ~= "circle" and V3(radius * 2, part.Size.Y, radius * 2) or nil,
        open = clock(), close = INF, tr = 0,
    }
    return addRecord(rec)
end
local function removeZoneRecords()
    for i = #HZ.attacks, 1, -1 do
        local rec = HZ.attacks[i]
        if rec.kind == "zone" then removeRecord(rec, clock()) end
    end
end
local function addVirtualAttack(name, cframe, size, open, close)
    local rec = {
        kind = "pred", name = name, key = string.lower(name), spawn = clock(),
        shape = "box", cframe = cframe, size = size, open = open, close = close, tr = 0.5,
    }
    HZ.attacks[#HZ.attacks + 1] = rec
    return rec
end

-- ------------------------------------------------------------------ the step
local lastSync = -INF
local function readerStep(now, step)
    if now - lastSync > 10 then lastSync = now syncClock() end
    promoteCandidates(now)
    local char = LocalPlayer.Character
    local root = char and char:FindFirstChild("HumanoidRootPart")
    local rx, rz
    if root then local p = root.Position rx, rz = p.X, p.Z end
    for i = #HZ.attacks, 1, -1 do
        local rec = HZ.attacks[i]
        local kind = rec.kind
        if kind == "model" then sampleModel(rec, now, step, rx, rz)
        elseif kind == "part" then samplePart(rec, now, step, rx, rz)
        elseif kind == "zone" then sampleZone(rec, now)
        elseif kind == "pred" then
            if now > rec.close + 0.3 or rec.dropped then removeRecord(rec, now) end
        end
    end
    for i = #recent, 1, -1 do
        if now - recent[i].removed > 1.0 then table.remove(recent, i) end
    end
    -- What can hurt now or within a second, within detection range: the HUD's
    -- count, the live feed and the highlights.
    local detected = {}
    local range = CFG.damageBrickDetectionRange
    for _, rec in ipairs(HZ.attacks) do
        local open, close = window(rec)
        if open and now <= close and now >= open - 1.0 and (rec.kind ~= "model" or CFG.usePrecast) then
            if rx == nil or rec.kind == "pred" then
                detected[#detected + 1] = rec
            else
                local ok, d = pcall(attackDistance, rec, rx, rz, now)
                if ok and d <= range then detected[#detected + 1] = rec end
            end
        end
    end
    HZ.detected = detected
    PC.zones = #detected
end

-- ------------------------------------------------------------------ start / stop
local function stopReader()
    for _, c in ipairs(connections) do pcall(function() c:Disconnect() end) end
    connections = {}
end
local function startReader()
    stopReader()
    pcall(function()
        local m = ReplicatedStorage:FindFirstChild("timeSync")
        if m then timeSync = require(m) end
    end)
    syncClock()
    connections[#connections + 1] = Workspace.ChildAdded:Connect(function(child)
        local ok, err = pcall(onChildAdded, child)
        if not ok then heavyDebug("Reader", "ChildAdded threw: " .. tostring(err)) end
    end)
    local pre = 0
    for _, c in ipairs(Workspace:GetChildren()) do
        if c:IsA("Model") and not c:FindFirstChildOfClass("Humanoid") and (c:FindFirstChild("hitBox") or c:FindFirstChild("precast")) then
            local rec = newModelRecord(c, clock() - 30)
            rec.pre = true
            pre = pre + 1
        end
    end
    local hooked = {}
    local remotes = ReplicatedStorage:FindFirstChild("remotes")
    if remotes then
        for _, r in ipairs(remotes:GetChildren()) do
            local n = r.Name
            if r:IsA("RemoteEvent") and (string.find(n, "BossSpecficEvents") or n == "mapSpecificEvent" or n == "bossSpecficEvents") then
                connections[#connections + 1] = r.OnClientEvent:Connect(function(name, args)
                    local ok, err = pcall(onEvent, n, name, args)
                    if not ok then heavyDebug("Reader", "event threw: " .. tostring(err)) end
                end)
                hooked[#hooked + 1] = n
            end
        end
    end
    PC.failed = false
    heavyDebug("Reader", fmt("Watching workspace (%d attack Models already present), %d boss remote(s), timeSync=%s.",
        pre, #hooked, tostring(timeSync ~= nil)))
end

S.readerStep = readerStep
S.startReader = startReader
S.stopReader = stopReader
S.scanEnemies = scanEnemies
S.recordHit = recordHit
S.attackDistance = attackDistance
S.attackWindow = window
S.attackLive = attackLive
S.gameTime = gameTime
S.addZoneRecord = addZoneRecord
S.removeZoneRecords = removeZoneRecords
S.addVirtualAttack = addVirtualAttack
S.invalidateAttackBook = invalidateAttackBook
S.readerEvents = events
-- Names the UI imports from the old modules, kept so ui.lua stays as it is.
S.stopWorldIndex = stopReader
S.stopBossEventListeners = stopReader
S.startPrecastListener = function() CFG.usePrecast = true end
S.clearPrecastZones = function() end
end
    end)()
    module(S)
end

-- ===================================== src/field.lua =====================================
do
    local module = (function()
-- field.lua - One danger field. For a point and a time: the worst of every
-- attack whose window contains that time (its shape at that time, with a hard
-- margin and a soft ring outside it) and every enemy's body. 1 is lethal.
--
-- The dodge samples the field about a thousand times per decision, so once
-- per frame every live attack is snapshotted into plain numbers (centre,
-- axes, half sizes, path) and the samples are pure arithmetic.
return function(S)
local CFG = S.CFG
local HZ = S.HZ
local attackWindow = S.attackWindow
local gameTime = S.gameTime

local HORIZON = 4.0          -- seconds ahead the snapshot keeps an attack for
local snap = {}              -- attack entries
local bodies = {}            -- enemy entries
local snapAt = -math.huge

-- Rebuild the snapshot for this frame.
local function fieldRefresh(now)
    snapAt = now
    local n = 0
    local usePrecast = CFG.usePrecast
    for i = 1, #HZ.attacks do
        local rec = HZ.attacks[i]
        if rec.kind ~= "model" or usePrecast then
            local open, close = attackWindow(rec)
            if open and close >= now and open <= now + HORIZON then
                local ok = pcall(function()
                    local e = { open = open, close = close }
                    if rec.kind == "part" then
                        e.kind = 3
                        e.r = rec.radius
                        local ev = rec.ev
                        if ev then
                            e.path = true
                            e.ox, e.oz = ev.origin.X, ev.origin.Z
                            e.lx, e.lz = ev.look.X, ev.look.Z
                            e.dist, e.dur, e.start = ev.dist, ev.dur, ev.start
                        else
                            local p = rec.pos
                            e.ox, e.oz = p.X, p.Z
                            local v = rec.vel
                            e.vx, e.vz = v and v.X or 0, v and v.Z or 0
                            e.t0 = rec.sampledAt
                        end
                    elseif rec.shape == "disc" then
                        e.kind = 2
                        local c = rec.center or rec.part.Position
                        e.ox, e.oz, e.r = c.X, c.Z, rec.radius
                    else
                        e.kind = 1
                        local cf = rec.cframe or rec.part.CFrame
                        local size = rec.size or rec.part.Size
                        local p = cf.Position
                        local rv, lv = cf.RightVector, cf.LookVector
                        e.ox, e.oz = p.X, p.Z
                        -- Planar axes; a pitched box is projected as if flat.
                        local rl = math.sqrt(rv.X * rv.X + rv.Z * rv.Z)
                        local ll = math.sqrt(lv.X * lv.X + lv.Z * lv.Z)
                        e.rx, e.rz = rl > 0.01 and rv.X / rl or 1, rl > 0.01 and rv.Z / rl or 0
                        e.lx, e.lz = ll > 0.01 and lv.X / ll or 0, ll > 0.01 and lv.Z / ll or 1
                        e.hx, e.hz = size.X * 0.5, size.Z * 0.5
                    end
                    n = n + 1
                    snap[n] = e
                end)
                if not ok then n = n end
            end
        end
    end
    for i = #snap, n + 1, -1 do snap[i] = nil end
    local m = 0
    for i = 1, #HZ.enemies do
        local en = HZ.enemies[i]
        local root = en.root
        if root.Parent then
            local p = root.Position
            m = m + 1
            local b = bodies[m] or {}
            b.x, b.z, b.hard = p.X, p.Z, (en.extent or 2) + 1.5
            bodies[m] = b
        end
    end
    for i = #bodies, m + 1, -1 do bodies[i] = nil end
end

-- Planar distance from (x, z) to entry e at time t; 0 or less inside.
local function entryDistance(e, x, z, t)
    local kind = e.kind
    if kind == 1 then
        local dx, dz = x - e.ox, z - e.oz
        local lx = dx * e.rx + dz * e.rz
        local lz = dx * e.lx + dz * e.lz
        local ax = math.abs(lx) - e.hx
        local az = math.abs(lz) - e.hz
        if ax < 0 then ax = 0 end
        if az < 0 then az = 0 end
        return math.sqrt(ax * ax + az * az)
    end
    local px, pz
    if kind == 2 then
        px, pz = e.ox, e.oz
    elseif e.path then
        local k = (gameTime(t) - e.start) / e.dur
        if k < 0 then k = 0 elseif k > 1 then k = 1 end
        px, pz = e.ox + e.lx * (k * e.dist), e.oz + e.lz * (k * e.dist)
    else
        local dt = t - e.t0
        if dt > CFG.projectileLookahead then dt = CFG.projectileLookahead end
        if dt < 0 then dt = 0 end
        px, pz = e.ox + e.vx * dt, e.oz + e.vz * dt
    end
    local dx, dz = px - x, pz - z
    return math.sqrt(dx * dx + dz * dz) - e.r
end

local function dangerAt(x, z, t)
    if t - snapAt > 1.5 then fieldRefresh(t) end
    local worst = 0
    local margin = CFG.damageBrickClearance
    local soft = CFG.preemptiveClearance
    for i = 1, #snap do
        local e = snap[i]
        if t >= e.open and t <= e.close then
            local d = entryDistance(e, x, z, t)
            local v
            if d <= margin then return 1
            elseif d < margin + soft then v = 0.6 * (1 - (d - margin) / soft)
            else v = 0 end
            if v > worst then worst = v end
        end
    end
    for i = 1, #bodies do
        local b = bodies[i]
        local dx, dz = b.x - x, b.z - z
        local d = math.sqrt(dx * dx + dz * dz)
        local v
        if d <= b.hard then return 1
        elseif d < b.hard + 4 then v = 0.3 * (1 - (d - b.hard) / 4)
        else v = 0 end
        if v > worst then worst = v end
    end
    return worst
end

-- Worst danger along the straight line from (x0,z0) to (x1,z1) walked at
-- `speed` starting at time t0, sampled every CFG.dodgeSampleSpacing studs at
-- the moment each sample would be reached. Returns worst, mean. `here` is
-- the danger at the start: the first samples are still inside whatever is
-- being left and that is not the line's fault.
local function dangerAlong(x0, z0, x1, z1, t0, speed, here)
    local dx, dz = x1 - x0, z1 - z0
    local len = math.sqrt(dx * dx + dz * dz)
    if len < 0.01 then return 0, 0 end
    local n = math.max(1, math.min(8, math.ceil(len / CFG.dodgeSampleSpacing)))
    local worst, sum = 0, 0
    for i = 1, n do
        local k = i / n
        local t = t0 + (len * k) / speed
        local v = dangerAt(x0 + dx * k, z0 + dz * k, t)
        if here and here > 0 and k < 0.5 then v = math.max(0, v - here) end
        if v > worst then worst = v end
        sum = sum + v
    end
    return worst, sum / n
end

-- Worst danger at a point over [t, t + dwell], sampled four times a second.
local function dangerOver(x, z, t, dwell)
    local worst = dangerAt(x, z, t)
    local steps = math.max(1, math.floor(dwell / 0.25))
    for i = 1, steps do
        if worst >= 1 then break end
        local v = dangerAt(x, z, t + i * 0.25)
        if v > worst then worst = v end
    end
    return worst
end

S.fieldRefresh = fieldRefresh
S.dangerAt = dangerAt
S.dangerAlong = dangerAlong
S.dangerOver = dangerOver
end
    end)()
    module(S)
end

-- ===================================== src/bosses.lua =====================================
do
    local module = (function()
-- bosses.lua - What is known about Northern Lands, measured in the real game
-- (Chris's capture of 2026-09-02) and read out of the client handler in the
-- place file. Per attack name: the age at which the precast flashes and the
-- hit lands. The Midgardian Champion's passive beams sweep twenty degrees per
-- half second, so from two beams the next ones are predicted before they
-- exist. The arena is the 217-stud cube FirstPart; a player outside it gets a
-- criss cross spawned on them, so after a respawn the standoff pull is strong.
return function(S)
local CFG = S.CFG
local RT = S.RT
local HZ = S.HZ
local Workspace = S.Workspace
local LocalPlayer = S.LocalPlayer
local heavyDebug = S.heavyDebug
local addVirtualAttack = S.addVirtualAttack

local clock = os.clock

-- Age (s after the Model appears) of the flash = the hit. From the capture:
-- beam 0.90-0.95, mage shot 0.95-1.03, spearman strike 0.86, warrior line
-- strike 0.65-0.67, warrior circle strike 0.63-0.68 (25-stud) / 0.35-0.40
-- (34-stud), jump slam 1.8 (from the older capture, one hit; unverified).
local FLASH = {
    firstbosspassivebeam = 0.92,
    northernmageshot = 0.98,
    spearmanstrikehitbox = 0.86,
    northernwarriorlinestrike = 0.66,
    northernwarriorcirclestrike = 0.65,
    firstbossjumpslam = 1.8,
}
local function flashTimeFor(rec)
    local T = FLASH[rec.key]
    if T and rec.key == "northernwarriorcirclestrike" and rec.part and rec.part.Size.Y >= 30 then T = 0.37 end
    return T
end

-- ------------------------------------------------------------------ the sweep
-- Beams are 250-stud lines through the boss, one every 0.5 s, twenty degrees
-- apart, in bursts of up to 13, ten seconds apart. Yaw is taken modulo 180
-- because a line through the centre is the same line turned round.
local BEAM = { step = 20, period = 0.5, ahead = 3 }
local sweep = { last = nil, prev = nil, preds = {} }

local function yawOf(cf)
    local l = cf.LookVector
    return (math.deg(math.atan2(l.X, -l.Z)) + 360) % 180
end
local function angleDelta(a, b)
    local d = (b - a) % 180
    if d > 90 then d = d - 180 end
    return d
end

local function onAttackShape(rec)
    if rec.kind ~= "model" or rec.key ~= "firstbosspassivebeam" or rec.pre or not rec.part then return end
    local yaw = yawOf(rec.part.CFrame)
    local now = clock()
    -- A predicted line that has now arrived is dropped for the real one.
    for i = #sweep.preds, 1, -1 do
        local p = sweep.preds[i]
        if math.abs(angleDelta(p.yaw, yaw)) < 6 or now > p.close then
            p.rec.dropped = true
            table.remove(sweep.preds, i)
        end
    end
    sweep.prev = sweep.last
    sweep.last = { yaw = yaw, at = rec.spawn, cf = rec.part.CFrame, size = rec.part.Size }
    local prev = sweep.prev
    if not prev or rec.spawn - prev.at > 1.2 then return end
    local delta = angleDelta(prev.yaw, yaw)
    if math.abs(math.abs(delta) - BEAM.step) > 6 then return end
    local dir = delta > 0 and 1 or -1
    local period = math.max(0.3, math.min(0.8, rec.spawn - prev.at))
    local T = FLASH.firstbosspassivebeam
    local centre = rec.part.CFrame.Position
    for k = 1, BEAM.ahead do
        local py = (yaw + dir * BEAM.step * k) % 180
        local spawnAt = rec.spawn + period * k
        local already = false
        for _, p in ipairs(sweep.preds) do
            if math.abs(angleDelta(p.yaw, py)) < 6 then already = true break end
        end
        if not already then
            local cf = CFrame.new(centre) * CFrame.Angles(0, -math.rad(py), 0)
            local open, close = spawnAt + T - CFG.dodgeLead, spawnAt + T + CFG.hitAfter
            local vrec = addVirtualAttack("firstBossPassiveBeam (predicted)", cf, rec.part.Size, open, close)
            sweep.preds[#sweep.preds + 1] = { yaw = py, close = close, rec = vrec }
        end
    end
end

-- A burst is in progress while a beam appeared in the last two seconds.
local function sweepActive(now)
    return sweep.last ~= nil and now - sweep.last.at < 2.0
end

-- ------------------------------------------------------------------ the arena
local arena
local function inArena(pos)
    if not arena then
        local fp = Workspace:FindFirstChild("FirstPart")
        if fp and fp:IsA("BasePart") then
            local c, s = fp.Position, fp.Size
            arena = { x0 = c.X - s.X * 0.5, x1 = c.X + s.X * 0.5, z0 = c.Z - s.Z * 0.5, z1 = c.Z + s.Z * 0.5 }
        else
            return true
        end
    end
    return pos.X >= arena.x0 and pos.X <= arena.x1 and pos.Z >= arena.z0 and pos.Z <= arena.z1
end

-- Where to stand off a given enemy right now.
local function standoffFor(enemy, now)
    if enemy.boss then
        if sweepActive(now) then return CFG.bossSweepStandoff end
        return CFG.bossStandoff
    end
    local extent = enemy.extent or 2
    local reach = extent + (enemy.melee or CFG.enemyMeleeReach) + 1
    return math.max(extent + 1, math.min(reach, CFG.attackRange - 1.5))
end

-- The approach is urgent outside the arena with a boss alive: the criss
-- cross is aimed at players standing there.
local function approachUrgency(now)
    local char = LocalPlayer.Character
    local root = char and char:FindFirstChild("HumanoidRootPart")
    if not root then return 1 end
    local bossAlive = false
    for _, e in ipairs(HZ.enemies) do if e.boss then bossAlive = true break end end
    if bossAlive and (not inArena(root.Position) or now - RT.respawnedAt < 6) then return 5 end
    return 1
end

local function onBossEvent(remoteName, name, args)
    if name == "First Boss Jump Up" then heavyDebug("Boss", "Jump up: expect a slam.") end
end

S.flashTimeFor = flashTimeFor
S.onAttackShape = onAttackShape
S.onBossEvent = onBossEvent
S.sweepActive = sweepActive
S.inArena = inArena
S.standoffFor = standoffFor
S.approachUrgency = approachUrgency
S.FLASH_TIMES = FLASH
end
    end)()
    module(S)
end

-- ===================================== src/mover.lua =====================================
do
    local module = (function()
-- mover.lua - The one thing that moves the character. A tween along the
-- floor: every frame the root is stepped toward the target at walking speed,
-- kept at floor height from a downward raycast, stopped by a wall raycast at
-- chest height. Never faster than CFG.moveSpeed, never airborne, never a
-- state the client anticheat objects to. Or, in walk mode, Humanoid:MoveTo.
return function(S)
local CFG = S.CFG
local RT = S.RT
local Workspace = S.Workspace
local LocalPlayer = S.LocalPlayer

local V3 = Vector3.new
local MV = { target = nil, speed = 16, owner = "", face = nil, blocked = false, arrived = false,
             lastMoveTo = nil, walkForced = false, driving = false }

local rayParams
local function params()
    if not rayParams then
        rayParams = RaycastParams.new()
        rayParams.FilterType = Enum.RaycastFilterType.Exclude
        pcall(function() rayParams.RespectCanCollide = true end)
    end
    local excl = {}
    local char = LocalPlayer.Character
    if char then excl[#excl + 1] = char end
    if RT.visualRoot then excl[#excl + 1] = RT.visualRoot end
    rayParams.FilterDescendantsInstances = excl
    return rayParams
end

-- Floor height under (x, z) searched from y + 3 down to y - 12; nil = no floor.
local function floorAt(x, y, z)
    local r = Workspace:Raycast(V3(x, y + 3, z), V3(0, -15, 0), params())
    if r then return r.Position.Y end
    return nil
end

-- A solid between two points at knee and chest height. Steps count as floor.
local function wallBetween(from, to)
    local dir = to - from
    local flat = V3(dir.X, 0, dir.Z)
    if flat.Magnitude < 0.05 then return false end
    for _, h in ipairs({ 1.2, 2.6 }) do
        local r = Workspace:Raycast(from + V3(0, h, 0), flat, params())
        if r and r.Instance then
            -- A low, walkable-topped edge is a step, not a wall.
            if not (h == 1.2 and r.Normal.Y > 0.5) then return true, r end
        end
    end
    return false
end

local function moverStop()
    if MV.target == nil and not MV.driving then return end
    MV.target = nil
    MV.driving = false
    MV.lastMoveTo = nil
    local char = LocalPlayer.Character
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    local root = char and char:FindFirstChild("HumanoidRootPart")
    if hum and root then
        pcall(function() hum:MoveTo(root.Position) end)
        hum.AutoRotate = true
    end
end

-- Ask to be at `point`, moving at `speed`, facing `face` (a position) or the
-- way we go. `owner` is a label for the HUD. Called every decision; cheap.
local function moveTo(point, speed, owner, face, forceWalk)
    MV.target = point
    MV.speed = speed or CFG.moveSpeed
    MV.owner = owner or ""
    MV.face = face
    MV.walkForced = forceWalk == true
    MV.arrived = false
end

-- Turn the root toward a position without moving it (standing and casting).
local function faceToward(root, hum, target)
    if not root or not target then return end
    local p = root.Position
    local look = V3(target.X - p.X, 0, target.Z - p.Z)
    if look.Magnitude < 0.5 then return end
    hum.AutoRotate = false
    root.CFrame = CFrame.lookAt(p, p + look.Unit)
end

-- One frame of movement. Returns true while driving.
local function moverStep(dt)
    local char = LocalPlayer.Character
    local root = char and char:FindFirstChild("HumanoidRootPart")
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    if not root or not hum or not MV.target then return false end
    local pos = root.Position
    local target = MV.target
    local dx, dz = target.X - pos.X, target.Z - pos.Z
    local dist = math.sqrt(dx * dx + dz * dz)
    if dist <= CFG.moveArriveRadius then
        MV.arrived = true
        if MV.driving and CFG.moveMode ~= "tween" then pcall(function() hum:MoveTo(pos) end) end
        MV.driving = false
        return false
    end
    MV.driving = true
    if CFG.moveMode ~= "tween" or MV.walkForced then
        hum.AutoRotate = true
        if not MV.lastMoveTo or (MV.lastMoveTo - target).Magnitude > 1 then
            MV.lastMoveTo = target
            pcall(function() hum:MoveTo(target) end)
        end
        return true
    end
    local step = math.min(dist, MV.speed * dt)
    local nx, nz = pos.X + dx / dist * step, pos.Z + dz / dist * step
    local fy = floorAt(nx, pos.Y, nz)
    if not fy then MV.blocked = true return true end
    local ny = fy + hum.HipHeight + root.Size.Y * 0.5
    local rise = ny - pos.Y
    if rise > CFG.maxStepHeight + 0.5 or -rise > CFG.dodgeMaxDrop then MV.blocked = true return true end
    local next = V3(nx, ny, nz)
    if wallBetween(pos, next) then MV.blocked = true return true end
    MV.blocked = false
    local look
    if MV.face then look = V3(MV.face.X - nx, 0, MV.face.Z - nz) else look = V3(dx, 0, dz) end
    hum.AutoRotate = false
    if look.Magnitude > 0.1 then
        root.CFrame = CFrame.lookAt(next, next + look.Unit)
    else
        root.CFrame = CFrame.new(next) * (root.CFrame - root.CFrame.Position)
    end
    root.AssemblyLinearVelocity = V3(0, 0, 0)
    return true
end

S.MV = MV
S.moveTo = moveTo
S.moverStop = moverStop
S.moverStep = moverStep
S.faceToward = faceToward
S.floorAt = floorAt
S.wallBetween = wallBetween
end
    end)()
    module(S)
end

-- ===================================== src/dodge.lua =====================================
do
    local module = (function()
-- dodge.lua - Where to stand. A ring of candidates round the character,
-- each scored by the danger along the straight line to it (at the moments it
-- would be crossed) and at it for the dwell after arriving, plus a small
-- distance cost, a turn cost against the last heading, and a pull toward
-- where pursuit wants to be. The best one is the target; when here is fine
-- and pursuit is not blocked there is no target and pursuit drives.
return function(S)
local CFG = S.CFG
local DG = S.DG
local dangerAt = S.dangerAt
local dangerAlong = S.dangerAlong
local dangerOver = S.dangerOver
local floorAt = S.floorAt
local wallBetween = S.wallBetween

local V3 = Vector3.new
local INF = math.huge
local TAU = math.pi * 2

local function setDodgeActive(active)
    DG.active = active and true or false
    if not DG.active then
        DG.target = nil
        DG.gapWait = false
        DG.pursuitBlocked = false
        DG.dangerHere = 0
    end
end

local function decide(root, hum, now)
    local p = root.Position
    local x, z = p.X, p.Z
    local speed = CFG.dodgeSpeed
    local dwell = CFG.dodgeDwell
    local hereNow = dangerAt(x, z, now)
    local here = math.max(hereNow, dangerOver(x, z, now, math.min(dwell, 0.6)))
    DG.dangerHere = here
    local moveAt = CFG.dodgeMoveAt
    local goal = DG.goal
    local urgency = S.approachUrgency and S.approachUrgency(now) or 1

    -- Nothing on us and pursuit free to walk: no target, pursuit drives.
    if here < moveAt and not DG.pursuitBlocked then
        DG.target = nil
        DG.targetReason = "safe here"
        DG.gapWait = false
        DG.cands = {}
        return
    end

    local rings, rays, reach = CFG.dodgeRings, CFG.dodgeRays, CFG.dodgeReach
    local cands = {}
    local goalDistHere
    if goal then
        local gx, gz = goal.X - x, goal.Z - z
        goalDistHere = math.sqrt(gx * gx + gz * gz)
    end
    local hx, hz = 0, 0
    if DG.heading and now - DG.headingTime < 1.5 then hx, hz = DG.heading.X, DG.heading.Z end
    for r = 1, rings do
        local dist = reach * r / rings
        for i = 1, rays do
            local a = (i - 1) / rays * TAU + (r % 2) * (math.pi / rays)
            local ux, uz = math.cos(a), math.sin(a)
            local cx, cz = x + ux * dist, z + uz * dist
            local tArrive = now + dist / speed
            local lineWorst = dangerAlong(x, z, cx, cz, now, speed, hereNow)
            local arrive = dangerOver(cx, cz, tArrive, dwell)
            local danger = math.max(lineWorst, arrive)
            local cost = danger + CFG.dodgeDistanceCost * dist
            if goalDistHere then
                local gx, gz = goal.X - cx, goal.Z - cz
                local progress = goalDistHere - math.sqrt(gx * gx + gz * gz)
                cost = cost - CFG.dodgeApproachWeight * urgency * progress
            end
            if hx ~= 0 or hz ~= 0 then
                cost = cost + CFG.dodgeTurnCost * (1 - (ux * hx + uz * hz)) * 0.5
            end
            cands[#cands + 1] = { x = cx, z = cz, ux = ux, uz = uz, dist = dist, danger = danger, cost = cost }
        end
    end
    table.sort(cands, function(a, b) return a.cost < b.cost end)
    DG.cands = cands

    -- Validate the best few against the world: a floor to stand on within
    -- climb and drop limits, and no wall across the line.
    local best
    local budget = CFG.dodgeValidate
    for i = 1, math.min(#cands, budget) do
        local c = cands[i]
        local fy = floorAt(c.x, p.Y, c.z)
        if fy then
            local rise = fy - (p.Y - hum.HipHeight - root.Size.Y * 0.5)
            if rise <= CFG.dodgeMaxClimb and -rise <= CFG.dodgeMaxDrop then
                local target = V3(c.x, fy + hum.HipHeight + root.Size.Y * 0.5, c.z)
                if not wallBetween(p, target) then
                    c.target = target
                    c.valid = true
                    best = c
                    break
                end
            end
        end
        c.valid = false
    end

    if here >= moveAt then
        -- Something is on us or about to be: go to the least bad spot unless
        -- it is no better than here and here is not lethal.
        if best and (best.danger < here - 0.05 or here >= 1) then
            DG.target = best.target
            DG.targetReason = string.format("out (%.2f -> %.2f)", here, best.danger)
            DG.heading = V3(best.ux, 0, best.uz)
            DG.headingTime = now
            DG.gapWait = false
        else
            DG.target = nil
            DG.targetReason = "nowhere better"
            DG.gapWait = true
        end
        return
    end

    -- Here is safe and pursuit is blocked: a safe step that gains ground, or
    -- hold and wait for a gap.
    if best and best.danger < moveAt and goalDistHere then
        local gx, gz = goal.X - best.x, goal.Z - best.z
        local progress = goalDistHere - math.sqrt(gx * gx + gz * gz)
        if progress > 1.5 then
            DG.target = best.target
            DG.targetReason = string.format("in (%.2f)", best.danger)
            DG.heading = V3(best.ux, 0, best.uz)
            DG.headingTime = now
            DG.gapWait = false
            return
        end
    end
    DG.target = nil
    DG.targetReason = "waiting for a gap"
    DG.gapWait = true
end

-- Decide every frame while something is on us, otherwise on the interval.
local function dodgeStep(root, hum, now)
    if not DG.active then return end
    local due = now - DG.lastDecision >= CFG.dodgeInterval
    if not due and DG.dangerHere < CFG.dodgeMoveAt and DG.target == nil then return end
    DG.lastDecision = now
    decide(root, hum, now)
    if DG.target and S.MV.arrived then DG.target = nil end
end

S.setDodgeActive = setDodgeActive
S.dodgeStep = dodgeStep
end
    end)()
    module(S)
end

-- ===================================== src/pursuit.lua =====================================
do
    local module = (function()
-- pursuit.lua - Which enemy, where to stand off it, and how to get there:
-- straight at the standoff point when the way is clear, PathfindingService
-- once when a wall says otherwise, re-planned on block. Every step is asked
-- of the danger field first; a step that would cross something live is
-- refused and the dodge takes the approach one safe spot at a time.
return function(S)
local CFG = S.CFG
local RT = S.RT
local NAV = S.NAV
local HZ = S.HZ
local DG = S.DG
local Workspace = S.Workspace
local PathfindingService = S.PathfindingService
local LocalPlayer = S.LocalPlayer
local heavyDebug = S.heavyDebug
local heavyDebugThrottled = S.heavyDebugThrottled
local setMovementState = S.setMovementState
local dangerAlong = S.dangerAlong
local moveTo = S.moveTo
local moverStop = S.moverStop
local wallBetween = S.wallBetween
local MV = S.MV

local V3 = Vector3.new
local INF = math.huge
local clock = os.clock
local fmt = string.format

NAV.route = nil            -- { target, waypoints, index, computedAt, failed }
NAV.computing = false
NAV.blockedSince = nil
NAV.pointRoute = nil
NAV.pointProgressDistance = nil
NAV.pointProgressTime = 0

local function planar(a, b)
    local dx, dz = a.X - b.X, a.Z - b.Z
    return math.sqrt(dx * dx + dz * dz)
end

-- ------------------------------------------------------------------ target
local function pickTarget(root)
    local best, bestScore, count = nil, INF, 0
    local now = clock()
    local p = root.Position
    for _, e in ipairs(HZ.enemies) do
        if e.root.Parent and e.humanoid.Health > 0 then
            local bench = NAV.benched[e.model]
            if bench and now < bench then
                count = count + 1
            else
                if bench then NAV.benched[e.model] = nil end
                count = count + 1
                local d = planar(p, e.root.Position)
                local score
                if CFG.targetMode == "lowest HP" then
                    score = d <= CFG.targetHpRange and e.humanoid.Health or (1e9 + d)
                elseif CFG.targetMode == "highest HP" then
                    score = d <= CFG.targetHpRange and -e.humanoid.Health or (1e9 + d)
                else
                    score = d
                end
                if score < bestScore then best, bestScore = e, score end
            end
        end
    end
    NAV.cachedEntry = best
    NAV.cachedEnemy = best and best.model or nil
    NAV.cachedEnemyCount = count
    if S.updateEnemyDisplay then pcall(S.updateEnemyDisplay, NAV.cachedEnemy, count) end
    return best
end

-- ------------------------------------------------------------------ routes
local function computeRoute(slot, from, to)
    NAV.computing = true
    local ok, err = pcall(function()
        local path = PathfindingService:CreatePath({ AgentRadius = CFG.wallPadding, AgentHeight = 5, AgentCanJump = true })
        path:ComputeAsync(from, to)
        if path.Status == Enum.PathStatus.Success then
            slot.waypoints = path:GetWaypoints()
            slot.index = 2
            slot.failed = false
        else
            slot.waypoints = nil
            slot.failed = true
        end
    end)
    if not ok then slot.waypoints = nil slot.failed = true heavyDebug("Pursuit", "path threw: " .. tostring(err)) end
    slot.computedAt = clock()
    NAV.computing = false
end

-- The next point to walk to on the way to `goal`: the goal itself when the
-- straight line is clear, else the route's next waypoint (computing one if
-- there is none). Returns point, jump.
local function nextPoint(root, goal, slot)
    local p = root.Position
    local d = planar(p, goal)
    local direct = d < 8 or not wallBetween(p, V3(goal.X, p.Y, goal.Z))
    if direct then
        NAV.blockedSince = nil
        return goal, false
    end
    local now = clock()
    local stale = slot.target == nil or planar(slot.target, goal) > 4
        or (slot.computedAt and now - slot.computedAt > CFG.pathRecomputeInterval * (slot.failed and 3 or 8))
    if (stale or slot.needsRecompute) and not NAV.computing then
        slot.target = goal
        slot.needsRecompute = false
        local from = p
        task.spawn(function() computeRoute(slot, from, goal) end)
    end
    local wps = slot.waypoints
    if wps then
        while slot.index <= #wps do
            local wp = wps[slot.index]
            if planar(p, wp.Position) > 3.5 then break end
            slot.index = slot.index + 1
        end
        local wp = wps[slot.index]
        if wp then return wp.Position, wp.Action == Enum.PathWaypointAction.Jump end
    end
    return goal, false
end

-- Walk a step toward `point` unless the danger field says the next few studs
-- are not safe. Returns true when moving.
local function safeStep(root, point, speed, face, jump, owner)
    local p = root.Position
    local d = planar(p, point)
    if d < 0.3 then return false end
    local probe = math.min(d, CFG.dodgeStepProbe)
    local ux, uz = (point.X - p.X) / d, (point.Z - p.Z) / d
    local worst = dangerAlong(p.X, p.Z, p.X + ux * probe, p.Z + uz * probe, clock(), speed, nil)
    if worst >= CFG.dodgeMoveAt then
        DG.pursuitBlocked = true
        return false
    end
    DG.pursuitBlocked = false
    moveTo(point, speed, owner, face, jump)
    return true
end

-- ------------------------------------------------------------------ pursuit
local function resetPursuitPath()
    NAV.route = nil
    NAV.blockedSince = nil
    DG.goal = nil
end

local function pursuitStep(root, hum, now)
    local e = NAV.cachedEntry
    if not e or not e.root.Parent then resetPursuitPath() return end
    local ep, p = e.root.Position, root.Position
    local dist = planar(p, ep)
    local standoff = S.standoffFor(e, now)
    local ux, uz = 1, 0
    if dist > 0.1 then ux, uz = (p.X - ep.X) / dist, (p.Z - ep.Z) / dist end
    local goal = V3(ep.X + ux * standoff, p.Y, ep.Z + uz * standoff)
    DG.goal = goal
    local face = CFG.faceTarget and ep or nil
    local off = dist - standoff
    NAV.driving = false
    if math.abs(off) <= CFG.inRangeDeadband then
        moverStop()
        DG.pursuitBlocked = false
        setMovementState(fmt("HOLD %s at %.0f", e.name, dist))
        return
    end
    if off < 0 then
        -- Too close: back off to the standoff, straight away from it.
        if safeStep(root, goal, CFG.moveSpeed, face, false, "back") then
            NAV.driving = true
            setMovementState(fmt("BACK OFF %s (%.0f -> %.0f)", e.name, dist, standoff))
        else
            moverStop()
            setMovementState(fmt("too close to %s, way blocked", e.name))
        end
        return
    end
    NAV.route = NAV.route or {}
    local point, jump = nextPoint(root, goal, NAV.route)
    if safeStep(root, point, CFG.moveSpeed, face, jump, "pursuit") then
        NAV.driving = true
        setMovementState(fmt("PURSUE %s (%.0f -> %.0f)%s", e.name, dist, standoff, NAV.route.waypoints and " [path]" or ""))
        if MV.blocked then
            NAV.blockedSince = NAV.blockedSince or now
            if now - NAV.blockedSince > 0.6 then
                NAV.route.needsRecompute = true
                NAV.blockedSince = now
                if NAV.route.failed then
                    NAV.benched[e.model] = now + 10
                    heavyDebug("Pursuit", "No route to " .. e.name .. "; benched for ten seconds.")
                end
            end
        else
            NAV.blockedSince = nil
        end
    else
        moverStop()
        setMovementState(fmt("HOLD for a gap (%s at %.0f)", e.name, dist))
    end
end

-- ------------------------------------------------------------------ points (path.lua)
local function clearPointRoute()
    NAV.pointRoute = nil
    NAV.pointProgressDistance = nil
    NAV.pointProgressTime = 0
    NAV.walkAnchor = nil
end

-- Walk toward a static point (the manual waypath). Returns distance, stuck.
local function walkTowardPoint(hum, root, point)
    NAV.driving = true
    local now = clock()
    local p = root.Position
    local distance = planar(p, point)
    if not NAV.pointRoute or planar(NAV.pointRoute.goal, point) > 3 then
        NAV.pointRoute = { goal = point }
        NAV.pointProgressDistance = distance
        NAV.pointProgressTime = now
    elseif distance < NAV.pointProgressDistance - 1.5 then
        NAV.pointProgressDistance = distance
        NAV.pointProgressTime = now
    end
    local stuck = now - NAV.pointProgressTime >= CFG.pointGiveUpTime
    local slot = NAV.pointRoute
    local next, jump = nextPoint(root, point, slot)
    if safeStep(root, next, CFG.moveSpeed, nil, jump, "path") then
        if MV.blocked then slot.needsRecompute = true end
    else
        moverStop()
    end
    return distance, stuck
end

local function followPath(hum, root)
    local wp = NAV.waypath[NAV.pathIndex]
    if not wp then
        if CFG.loopPath and #NAV.waypath > 0 then NAV.pathIndex = 1 wp = NAV.waypath[1] else return false end
    end
    local distance, stuck = walkTowardPoint(hum, root, wp)
    setMovementState(fmt("PATH waypoint %d/%d (%.0f)", NAV.pathIndex, #NAV.waypath, distance))
    if stuck then
        heavyDebugThrottled("path_stuck", 5, "Path", "No progress toward the waypoint; skipping it.")
        NAV.pathIndex = NAV.pathIndex + 1
        clearPointRoute()
    end
    return true
end

S.pickTarget = pickTarget
S.pursuitStep = pursuitStep
S.resetPursuitPath = resetPursuitPath
S.walkTowardPoint = walkTowardPoint
S.clearPointRoute = clearPointRoute
S.followPath = followPath
end
    end)()
    module(S)
end

-- ===================================== src/draw.lua =====================================
do
    local module = (function()
-- draw.lua - Everything drawn in the world and the live feed. Only what can
-- hurt is drawn: red for an attack whose window is open, amber for one that
-- opens within a second. The dodge's candidates, its target and its search
-- ring; the character's own hitbox and ability radius; the route.
return function(S)
local CFG = S.CFG
local RT = S.RT
local UI = S.UI
local HZ = S.HZ
local DG = S.DG
local NAV = S.NAV
local K = S.UIKit
local LocalPlayer = S.LocalPlayer
local getVisualRoot = S.getVisualRoot
local attackWindow = S.attackWindow

local V3 = Vector3.new
local clock = os.clock
local folder
local function root()
    if folder and folder.Parent then return folder end
    folder = Instance.new("Folder")
    folder.Name = "Overlays"
    folder.Parent = getVisualRoot()
    return folder
end

-- A pool of anchored, non-colliding parts reused frame to frame.
local function makePool(name, shape)
    local pool = { parts = {}, used = 0, name = name, shape = shape }
    function pool.take()
        pool.used = pool.used + 1
        local part = pool.parts[pool.used]
        if not part or not part.Parent then
            part = Instance.new("Part")
            part.Name = name
            part.Anchored = true
            part.CanCollide = false
            part.CanQuery = false
            part.CanTouch = false
            part.CastShadow = false
            part.Material = Enum.Material.Neon
            if shape then part.Shape = shape end
            part.Parent = root()
            pool.parts[pool.used] = part
        end
        return part
    end
    function pool.reset() pool.used = 0 end
    function pool.hide()
        for i = pool.used + 1, #pool.parts do
            local part = pool.parts[i]
            if part.Parent and part.Transparency < 1 then part.Transparency = 1 end
        end
    end
    function pool.clear()
        for _, part in ipairs(pool.parts) do if part.Parent then part:Destroy() end end
        pool.parts = {}
        pool.used = 0
    end
    return pool
end
local hazardBoxes = makePool("Hazard")
local hazardDiscs = makePool("HazardDisc", Enum.PartType.Cylinder)
local candDiscs = makePool("Candidate", Enum.PartType.Cylinder)
local misc = makePool("Overlay")
local routeOrbs = makePool("Route", Enum.PartType.Ball)

-- ------------------------------------------------------------------ hazards
local function clearHazardHighlights()
    hazardBoxes.clear()
    hazardDiscs.clear()
end
local function updateHazardHighlights()
    hazardBoxes.reset()
    hazardDiscs.reset()
    if RT.renderHazardsEnabled and CFG.showPrecast and not RT.destroyed then
        local now = clock()
        local shown = 0
        for _, rec in ipairs(HZ.detected) do
            if shown >= CFG.maxHazardOverlays then break end
            local open, close = attackWindow(rec)
            if open then
                local live = now >= open and now <= close
                local colour = live and CFG.colorTelegraph or CFG.colorTelegraphPending
                local ok = pcall(function()
                    if rec.kind == "part" then
                        local part = hazardDiscs.take()
                        local p = rec.inst.Position
                        part.Size = V3(0.6, rec.radius * 2, rec.radius * 2)
                        part.CFrame = CFrame.new(p.X, p.Y, p.Z) * CFrame.Angles(0, 0, math.rad(90))
                        part.Color = colour
                        part.Transparency = 0.55
                    elseif rec.shape == "disc" then
                        local part = hazardDiscs.take()
                        local c = rec.center or rec.part.Position
                        part.Size = V3(0.6, rec.radius * 2, rec.radius * 2)
                        part.CFrame = CFrame.new(c.X, c.Y, c.Z) * CFrame.Angles(0, 0, math.rad(90))
                        part.Color = colour
                        part.Transparency = 0.55
                    else
                        local part = hazardBoxes.take()
                        local cf = rec.cframe or rec.part.CFrame
                        local size = rec.size or rec.part.Size
                        part.Size = V3(size.X, 0.6, size.Z)
                        part.CFrame = cf - V3(0, size.Y * 0.5 - 0.5, 0)
                        part.Color = colour
                        part.Transparency = live and 0.45 or 0.7
                    end
                end)
                if ok then shown = shown + 1 end
            end
        end
    end
    hazardBoxes.hide()
    hazardDiscs.hide()
end

-- ------------------------------------------------------------------ the dodge
local function updateDodgeVisuals()
    candDiscs.reset()
    misc.reset()
    if DG.active and not RT.destroyed and RT.farmEnabled then
        local char = LocalPlayer.Character
        local rootPart = char and char:FindFirstChild("HumanoidRootPart")
        if rootPart then
            local y = rootPart.Position.Y - 2.5
            if CFG.dodgeShowField then
                for i, c in ipairs(DG.cands) do
                    if i > 72 then break end
                    local part = candDiscs.take()
                    part.Size = V3(0.3, 1.2, 1.2)
                    part.CFrame = CFrame.new(c.x, y, c.z) * CFrame.Angles(0, 0, math.rad(90))
                    local d = math.max(0, math.min(1, c.danger))
                    part.Color = CFG.colorDodgeSafe:Lerp(CFG.colorDodgeDanger, d)
                    part.Transparency = c.valid == false and 0.85 or 0.4
                end
            end
            if CFG.dodgeShowRange then
                local ring = misc.take()
                ring.Shape = Enum.PartType.Cylinder
                ring.Size = V3(0.2, CFG.dodgeReach * 2, CFG.dodgeReach * 2)
                ring.CFrame = CFrame.new(rootPart.Position.X, y - 0.2, rootPart.Position.Z) * CFrame.Angles(0, 0, math.rad(90))
                ring.Color = CFG.colorDodgeTarget
                ring.Transparency = 0.92
            end
            if CFG.dodgeShowTarget and DG.target then
                local box = misc.take()
                box.Shape = Enum.PartType.Block
                box.Size = V3(2.5, 3.5, 2.5)
                box.CFrame = CFrame.new(DG.target)
                box.Color = CFG.colorDodgeTarget
                box.Transparency = 0.6
            end
            if CFG.showEscapeRoute and DG.target then
                local line = misc.take()
                line.Shape = Enum.PartType.Block
                local a, b = rootPart.Position, DG.target
                local len = (b - a).Magnitude
                if len > 0.5 then
                    line.Size = V3(0.3, 0.3, len)
                    line.CFrame = CFrame.lookAt((a + b) * 0.5, b)
                    line.Color = CFG.colorEscape
                    line.Transparency = 0.3
                end
            end
        end
    end
    candDiscs.hide()
    misc.hide()
end

-- ------------------------------------------------------------------ the route
local function clearRenderedPath() routeOrbs.clear() end
local function renderCurrentPath()
    routeOrbs.reset()
    if RT.renderPathEnabled and NAV.route and NAV.route.waypoints and not RT.destroyed then
        local wps = NAV.route.waypoints
        for i = NAV.route.index or 1, #wps do
            if routeOrbs.used >= 24 then break end
            local orb = routeOrbs.take()
            orb.Size = V3(0.8, 0.8, 0.8)
            orb.CFrame = CFrame.new(wps[i].Position + V3(0, 0.5, 0))
            orb.Color = CFG.colorPursuit
            orb.Transparency = 0.3
        end
    end
    routeOrbs.hide()
end

-- ------------------------------------------------------------------ own hitbox
local adornFolder
local function clearHitboxVisualizer()
    if adornFolder then adornFolder:Destroy() adornFolder = nil end
end
local function updateHitboxVisualizer()
    local wantHitbox = RT.renderHitboxEnabled and RT.farmEnabled
    local wantRadius = CFG.showAbilityRadius
    local char = LocalPlayer.Character
    local rootPart = char and char:FindFirstChild("HumanoidRootPart")
    if not rootPart or (not wantHitbox and not wantRadius) or RT.destroyed then
        clearHitboxVisualizer()
        return
    end
    if not adornFolder or not adornFolder.Parent then
        adornFolder = Instance.new("Folder")
        adornFolder.Name = "PlayerAdornments"
        adornFolder.Parent = getVisualRoot()
    end
    local box = adornFolder:FindFirstChild("HitboxSolidBox")
    if wantHitbox then
        if not box then
            box = Instance.new("SelectionBox")
            box.Name = "HitboxSolidBox"
            box.LineThickness = 0.03
            box.SurfaceTransparency = 0.8
            box.Parent = adornFolder
        end
        box.Color3 = CFG.colorHitbox
        box.SurfaceColor3 = CFG.colorHitbox
        if box.Adornee ~= rootPart then box.Adornee = rootPart end
    elseif box then
        box:Destroy()
    end
    local sphere = adornFolder:FindFirstChild("AbilityRadius")
    if wantRadius then
        if not sphere then
            sphere = Instance.new("SphereHandleAdornment")
            sphere.Name = "AbilityRadius"
            sphere.Transparency = 0.82
            sphere.AlwaysOnTop = false
            sphere.Parent = adornFolder
        end
        sphere.Color3 = CFG.colorAbilityRadius
        if sphere.Adornee ~= rootPart then sphere.Adornee = rootPart end
        if sphere.Radius ~= CFG.abilityRadius then sphere.Radius = CFG.abilityRadius end
    elseif sphere then
        sphere:Destroy()
    end
end

-- ------------------------------------------------------------------ the feed
local function updateFeed()
    local list = UI.telegraphFeedList
    if not list or not list.Parent then return end
    if UI.damageBrickCountLabel then UI.damageBrickCountLabel.Text = "Telegraphs Active: " .. #HZ.detected end
    for _, child in ipairs(list:GetChildren()) do
        if child:IsA("GuiObject") then child:Destroy() end
    end
    local now = clock()
    for i, rec in ipairs(HZ.detected) do
        if i > 16 then break end
        local open, close = attackWindow(rec)
        local state = "coming"
        if open and now >= open and now <= close then state = "LIVE"
        elseif open then state = string.format("in %.1fs", open - now) end
        local text = string.format("%s  %s  age %.1f%s", rec.name, state, now - rec.spawn,
            rec.flashTime and string.format("  flash %.2f", rec.flashTime) or "")
        local label = K.label(list, text, "captionSub", i)
        label.Size = UDim2.new(1, 0, 0, 18)
        label.TextTruncate = Enum.TextTruncate.AtEnd
    end
end

-- ------------------------------------------------------------------ the step
local lastHazard, lastDodge, lastFeed = -math.huge, -math.huge, -math.huge
local function drawStep(now)
    if RT.destroyed then return end
    if now - lastHazard >= CFG.visualRefreshInterval then
        lastHazard = now
        pcall(updateHazardHighlights)
        pcall(updateHitboxVisualizer)
        pcall(renderCurrentPath)
    end
    if now - lastDodge >= 0.1 then
        lastDodge = now
        pcall(updateDodgeVisuals)
    end
    if now - lastFeed >= 0.5 then
        lastFeed = now
        pcall(updateFeed)
    end
end

local function clearAll()
    clearHazardHighlights()
    candDiscs.clear()
    misc.clear()
    routeOrbs.clear()
    clearHitboxVisualizer()
end

S.drawStep = drawStep
S.clearHazardHighlights = clearHazardHighlights
S.updateHazardHighlights = updateHazardHighlights
S.clearHitboxVisualizer = clearHitboxVisualizer
S.updateHitboxVisualizer = updateHitboxVisualizer
S.renderCurrentPath = renderCurrentPath
S.clearRenderedPath = clearRenderedPath
S.clearDrawings = clearAll
-- Names the UI imports from the old modules. Walls are not catalogued any
-- more; the escape route is the dodge line drawn with the box.
S.clearWallHighlights = function() end
S.updateWallHighlights = function() end
S.resetWallCatalog = function() end
S.renderEscapeRoute = function() end
S.clearEscapeRoute = function() end
S.clearEscapeNodes = function() end
S.destroyFacingRig = function() end
end
    end)()
    module(S)
end

-- ===================================== src/tools.lua =====================================
do
    local module = (function()
-- tools.lua - The Attacks panel's tools: the pickers (add an attack by
-- clicking it, mark your own effects, keep parts visible, draw a zone), the
-- Attack Book helpers, the hand-drawn zones, low detail, and the capture
-- file - the same report the standalone probe writes, from the reader's own
-- records.
return function(S)
local CFG = S.CFG
local RT = S.RT
local HZ = S.HZ
local LD = S.LD
local ZN = S.ZN
local Workspace = S.Workspace
local LocalPlayer = S.LocalPlayer
local heavyDebug = S.heavyDebug
local getVisualRoot = S.getVisualRoot
local addZoneRecord = S.addZoneRecord
local removeZoneRecords = S.removeZoneRecords
local invalidateAttackBook = S.invalidateAttackBook
local attackWindow = S.attackWindow

local V3 = Vector3.new
local clock = os.clock
local fmt = string.format

-- ------------------------------------------------------------------ the book
local function describeRecord(record)
    local st = HZ.stats[string.lower(record.name or "")]
    local parts = {}
    if st then
        parts[#parts + 1] = fmt("%d seen", st.n)
        if st.flashN > 0 then parts[#parts + 1] = fmt("flash %.2fs", st.flashSum / st.flashN) end
    end
    local T = S.FLASH_TIMES and S.FLASH_TIMES[string.lower(record.name or "")]
    if T then parts[#parts + 1] = fmt("table %.2fs", T) end
    if #parts == 0 then return "not seen yet" end
    return table.concat(parts, ", ")
end
local function removeAttackRecord(index)
    local r = table.remove(HZ.attackBook, index)
    if not r then return end
    invalidateAttackBook()
    if S.refreshAttackBookPanel then S.refreshAttackBookPanel() end
end
local function clearAttackBook()
    HZ.attackBook = {}
    invalidateAttackBook()
    if S.refreshAttackBookPanel then S.refreshAttackBookPanel() end
end

-- ------------------------------------------------------------------ zones
local function serializeZones()
    local out = {}
    for _, def in ipairs(ZN.defs) do
        out[#out + 1] = { name = def.name, parentName = def.parentName, shape = def.shape, radius = def.radius, height = def.height }
    end
    return out
end
local function rebuildZones()
    removeZoneRecords()
    if #ZN.defs == 0 then return end
    local map = Workspace:FindFirstChild("Map") or Workspace
    local count = 0
    for _, def in ipairs(ZN.defs) do
        for _, inst in ipairs(map:GetDescendants()) do
            if inst:IsA("BasePart") and inst.Name == def.name
                and (def.parentName == "" or (inst.Parent and inst.Parent.Name == def.parentName)) then
                addZoneRecord(inst, def.shape, def.radius, "zone " .. def.name)
                count = count + 1
                if count > 200 then break end
            end
        end
    end
    heavyDebug("Zone", fmt("%d zone volume(s) live from %d definition(s).", count, #ZN.defs))
end
local function loadZones(list)
    ZN.defs = {}
    if type(list) == "table" then
        for _, z in ipairs(list) do
            if type(z) == "table" and type(z.name) == "string" then
                ZN.defs[#ZN.defs + 1] = { name = z.name, parentName = tostring(z.parentName or ""), shape = z.shape == "square" and "square" or "circle",
                    radius = tonumber(z.radius) or CFG.zoneDefaultRadius, height = tonumber(z.height) or CFG.zoneDefaultHeight }
            end
        end
    end
    rebuildZones()
    if S.refreshZonePanel then S.refreshZonePanel() end
    return #ZN.defs
end
local function addZoneDef(part, shape, radius, height)
    radius = math.max(CFG.zoneMinRadius, math.min(CFG.zoneMaxRadius, radius or CFG.zoneDefaultRadius))
    ZN.defs[#ZN.defs + 1] = { name = part.Name, parentName = part.Parent and part.Parent.Name or "", shape = shape or "circle", radius = radius, height = height or CFG.zoneDefaultHeight }
    rebuildZones()
    if S.refreshZonePanel then S.refreshZonePanel() end
end
local function removeZoneDef(index)
    if table.remove(ZN.defs, index) then
        rebuildZones()
        if S.refreshZonePanel then S.refreshZonePanel() end
    end
end
local preview
local function clearZonePreview()
    if preview then preview:Destroy() preview = nil end
    ZN.dragging = false
    ZN.root = nil
end
local function updateZonePreview()
    if not ZN.root or not ZN.root.Parent then return end
    if not preview then
        preview = Instance.new("Part")
        preview.Name = "ZonePreview"
        preview.Anchored = true
        preview.CanCollide = false
        preview.CanQuery = false
        preview.Material = Enum.Material.Neon
        preview.Color = CFG.colorTelegraphPending
        preview.Transparency = 0.6
        preview.Parent = getVisualRoot()
    end
    local r = ZN.draftRadius
    if ZN.draftShape == "circle" then
        preview.Shape = Enum.PartType.Cylinder
        preview.Size = V3(0.5, r * 2, r * 2)
        preview.CFrame = CFrame.new(ZN.root.Position) * CFrame.Angles(0, 0, math.rad(90))
    else
        preview.Shape = Enum.PartType.Block
        preview.Size = V3(r * 2, 0.5, r * 2)
        preview.CFrame = CFrame.new(ZN.root.Position)
    end
end

-- ------------------------------------------------------------------ pickers
local hover
local function clearHoverHighlight()
    if hover then hover:Destroy() hover = nil end
end
local function setHoverHighlight(target)
    if not target or not target:IsA("BasePart") then clearHoverHighlight() return end
    if not hover then
        hover = Instance.new("SelectionBox")
        hover.Name = "PickerHover"
        hover.LineThickness = 0.04
        hover.Color3 = CFG.accentColor
        hover.Parent = getVisualRoot()
    end
    hover.Adornee = target
end
local function attackNameOf(part)
    local node = part
    for _ = 1, 3 do
        if node:IsA("Model") then return node.Name end
        node = node.Parent
        if not node or node == Workspace then break end
    end
    return part.Name
end
local function togglePickedTelegraph(target)
    if not target or not target:IsA("BasePart") then return end
    local name = attackNameOf(target)
    local key = string.lower(name)
    if HZ.learnedNames[key] then
        HZ.learnedNames[key] = nil
        heavyDebug("Picker", "Forgot '" .. name .. "'.")
    else
        HZ.learnedNames[key] = true
        if not HZ.bookByName[key] then
            HZ.attackBook[#HZ.attackBook + 1] = { name = name, enabled = true, hits = 0, damage = 0 }
            invalidateAttackBook()
        end
        heavyDebug("Picker", "Added '" .. name .. "' to the book; parts of that name are tracked as attacks.")
    end
    if S.refreshNameLists then S.refreshNameLists() end
    if S.refreshAttackBookPanel then S.refreshAttackBookPanel() end
end
local function togglePickedOwn(target)
    if not target or not target:IsA("BasePart") then return end
    local key = string.lower(attackNameOf(target))
    HZ.ownNames[key] = not HZ.ownNames[key] or nil
    heavyDebug("Picker", (HZ.ownNames[key] and "Marked '" or "Unmarked '") .. key .. "' as our own effect.")
    if S.refreshNameLists then S.refreshNameLists() end
end
local function toggleKeepPart(target)
    if not target or not target:IsA("BasePart") then return end
    local name = target.Name
    LD.keepNames[name] = not LD.keepNames[name] or nil
    if S.refreshLowDetail then S.refreshLowDetail() end
    if S.refreshMapPanel then S.refreshMapPanel() end
end

local function setTelegraphPickerEnabled(enabled, mode)
    HZ.pickerEnabled = enabled and true or false
    HZ.ownPickerEnabled = enabled and mode == "own" or false
    LD.pickerEnabled = enabled and mode == "keep" or false
    ZN.pickerEnabled = enabled and mode == "zone" or false
    if not ZN.pickerEnabled then clearZonePreview() end
    for _, c in ipairs(HZ.pickerConnections) do c:Disconnect() end
    HZ.pickerConnections = {}
    if not enabled then clearHoverHighlight() return end
    HZ.pickerMouse = HZ.pickerMouse or LocalPlayer:GetMouse()
    local mouse = HZ.pickerMouse
    table.insert(HZ.pickerConnections, mouse.Move:Connect(function()
        if not HZ.pickerEnabled then return end
        if ZN.pickerEnabled and ZN.dragging and ZN.root and ZN.root.Parent then
            local hit = mouse.Hit
            if hit then
                local offset = hit.Position - ZN.root.Position
                ZN.draftRadius = math.max(CFG.zoneMinRadius, V3(offset.X, 0, offset.Z).Magnitude)
                updateZonePreview()
            end
            return
        end
        setHoverHighlight(mouse.Target)
    end))
    if ZN.pickerEnabled then
        table.insert(HZ.pickerConnections, mouse.Button1Up:Connect(function()
            if not ZN.dragging then return end
            ZN.dragging = false
            if ZN.root and ZN.root.Parent and ZN.draftRadius >= CFG.zoneMinRadius then
                addZoneDef(ZN.root, ZN.draftShape, ZN.draftRadius, CFG.zoneDefaultHeight)
            end
            clearZonePreview()
        end))
    end
    table.insert(HZ.pickerConnections, mouse.Button1Down:Connect(function()
        if not HZ.pickerEnabled then return end
        local target = mouse.Target
        if ZN.pickerEnabled then
            if target and target:IsA("BasePart") then
                ZN.root = target
                ZN.dragging = true
                ZN.draftRadius = CFG.zoneDefaultRadius
                updateZonePreview()
            end
        elseif LD.pickerEnabled then toggleKeepPart(target)
        elseif HZ.ownPickerEnabled then togglePickedOwn(target)
        else togglePickedTelegraph(target) end
    end))
    heavyDebug("Picker", "Picker armed (" .. tostring(mode or "telegraph") .. ").")
end

-- ------------------------------------------------------------------ low detail
local sweepList, sweepCursor
local function restoreAllDetail()
    for part, t in pairs(LD.hidden) do
        pcall(function() part.LocalTransparencyModifier = t end)
    end
    LD.hidden = {}
    for effect in pairs(LD.disabledEffects) do
        pcall(function() effect.Enabled = true end)
    end
    LD.disabledEffects = {}
end
local function refreshLowDetail()
    if not LD.enabled then return end
    local map = Workspace:FindFirstChild("Map")
    sweepList = map and map:GetDescendants() or {}
    sweepCursor = 1
    LD.sweeping = true
end
local function setLowDetailEnabled(enabled)
    LD.enabled = enabled and true or false
    if LD.enabled then
        refreshLowDetail()
    else
        LD.sweeping = false
        restoreAllDetail()
    end
end
local function clearKeepList()
    LD.keepNames = {}
    if LD.enabled then restoreAllDetail() refreshLowDetail() end
    if S.refreshMapPanel then S.refreshMapPanel() end
end
local function lowDetailStep()
    if not LD.enabled or not LD.sweeping or not sweepList then return end
    local budget = CFG.lowDetailBudget
    while budget > 0 do
        local inst = sweepList[sweepCursor]
        if not inst then LD.sweeping = false return end
        sweepCursor = sweepCursor + 1
        budget = budget - 1
        if inst:IsA("BasePart") then
            if LD.keepNames[inst.Name] then
                if LD.hidden[inst] then
                    pcall(function() inst.LocalTransparencyModifier = LD.hidden[inst] end)
                    LD.hidden[inst] = nil
                end
            elseif not LD.hidden[inst] then
                LD.hidden[inst] = inst.LocalTransparencyModifier
                pcall(function() inst.LocalTransparencyModifier = 1 end)
            end
        elseif CFG.lowDetailKillEffects and (inst:IsA("ParticleEmitter") or inst:IsA("Trail") or inst:IsA("Beam")) then
            if inst.Enabled and not LD.disabledEffects[inst] then
                LD.disabledEffects[inst] = true
                pcall(function() inst.Enabled = false end)
            end
        end
    end
end

-- ------------------------------------------------------------------ the capture
local function clearAttackLog()
    HZ.finished = {}
    HZ.hitLog = {}
    HZ.stats = {}
    HZ.captureStart = clock()
end
local function recLine(rec)
    local now = clock()
    local spans = table.concat(rec.spans or {}, " ")
    if rec.inside then spans = spans .. (spans ~= "" and " " or "") .. fmt("%.2f-now", rec.insideAt - rec.spawn) end
    return fmt("%-26s @%7.1f %s dist=? size=%s tr0=%s vis@%s flash@%s fade@%s rm@%s T=%s trace=[%s] inside=[%s]",
        rec.name, rec.spawn - (HZ.captureStart or 0), rec.pre and "*" or " ", rec.sizeText or "?",
        rec.trace and rec.trace[1] or "-",
        rec.visAt and fmt("%.2f", rec.visAt - rec.spawn) or "-",
        rec.flashAt and fmt("%.2f", rec.flashAt - rec.spawn) or "-",
        rec.fadeAt and fmt("%.2f", rec.fadeAt - rec.spawn) or "-",
        rec.removed and fmt("%.2f", rec.removed - rec.spawn) or "live",
        rec.flashTime and fmt("%.2f", rec.flashTime) or "-",
        table.concat(rec.trace or {}, " "), spans)
end
local function buildAttackLog()
    local out = {}
    local function w(s) out[#out + 1] = s end
    local map = Workspace:FindFirstChild("dungeonName")
    w(fmt("DungeonAutofarm %s attack capture  map=%s  %s  recording=%s", S.SCRIPT_VERSION, map and map.Value or RT.currentMap, os.date("%Y-%m-%d %H:%M:%S"), tostring(CFG.diagnoseAttacks)))
    w("SUMMARY by name - n seen; measured flash age (mean); inside@age=s: seconds the root spent inside at that age (0.25 s buckets); HIT@age=n: hits while inside")
    local names = {}
    for name in pairs(HZ.stats) do names[#names + 1] = name end
    table.sort(names)
    for _, name in ipairs(names) do
        local st = HZ.stats[name]
        local ins, hs, totalIn, totalHits = {}, {}, 0, 0
        for b = 0, 48 do
            if st.inside[b] then ins[#ins + 1] = fmt("%.2f=%.1f", b * 0.25, st.inside[b]) totalIn = totalIn + st.inside[b] end
            if st.hits[b] then hs[#hs + 1] = fmt("%.2f=%d", b * 0.25, st.hits[b]) totalHits = totalHits + st.hits[b] end
        end
        w(fmt("%-28s n=%-4d flash=%s  inside %.1fs [%s]  HITS %d [%s]", name, st.n,
            st.flashN > 0 and fmt("%.2f (%d)", st.flashSum / st.flashN, st.flashN) or "-", totalIn, table.concat(ins, " "), totalHits, table.concat(hs, " ")))
    end
    w("")
    w("HITS")
    for _, line in ipairs(HZ.hitLog) do w(line) end
    w("")
    w("ATTACKS (ended, then live) - spawn age, size, first transparency, first visible, flash, fade, removal, table time, trace=[age:transparency], inside=[spans]")
    for _, rec in ipairs(HZ.finished) do w(recLine(rec)) end
    for _, rec in ipairs(HZ.attacks) do if rec.kind ~= "pred" then w(recLine(rec)) end end
    w("")
    w("EVENTS (projectile-shaped boss events)")
    for _, ev in ipairs(S.readerEvents) do
        w(fmt("%s dist=%.0f dur=%.2f start%+.2f end%+.2f origin=(%.0f,%.0f,%.0f)", ev.name, ev.dist, ev.dur,
            ev.start - S.gameTime(ev.at), ev.stop - S.gameTime(ev.at), ev.origin.X, ev.origin.Y, ev.origin.Z))
    end
    return table.concat(out, "\n")
end
local function saveAttackLog()
    if type(writefile) ~= "function" then return false, "no file access in this executor" end
    local ok, err = pcall(function() writefile(CFG.diagnoseFile, buildAttackLog()) end)
    if ok then heavyDebug("Capture", "Wrote " .. CFG.diagnoseFile) return true end
    return false, tostring(err)
end

S.describeRecord = describeRecord
S.removeAttackRecord = removeAttackRecord
S.clearAttackBook = clearAttackBook
S.serializeZones = serializeZones
S.loadZones = loadZones
S.rebuildZones = rebuildZones
S.addZoneDef = addZoneDef
S.removeZoneDef = removeZoneDef
S.clearZonePreview = clearZonePreview
S.clearHoverHighlight = clearHoverHighlight
S.setTelegraphPickerEnabled = setTelegraphPickerEnabled
S.setLowDetailEnabled = setLowDetailEnabled
S.refreshLowDetail = refreshLowDetail
S.restoreAllDetail = restoreAllDetail
S.clearKeepList = clearKeepList
S.lowDetailStep = lowDetailStep
S.saveAttackLog = saveAttackLog
S.clearAttackLog = clearAttackLog
S.buildAttackLog = buildAttackLog
end
    end)()
    module(S)
end

-- ===================================== src/path.lua =====================================
do
    local module = (function()
-- path.lua - Manual waypoint path: markers, editing, free-fly editor, progression, recovery.
-- Module contract: receives the shared table S. Everything this module needs from
-- earlier modules is pulled into locals below; everything later modules need is
-- assigned onto S at the bottom. Load order is fixed by main.lua / build.py.
return function(S)
local RT = S.RT
local NAV = S.NAV
local CFG = S.CFG
local heavyDebug = S.heavyDebug
local heavyDebugThrottled = S.heavyDebugThrottled
local UserInputService = S.UserInputService
local setMovementState = S.setMovementState
local LocalPlayer = S.LocalPlayer
local RunService = S.RunService
local Workspace = S.Workspace
local getVisualRoot = S.getVisualRoot
local walkTowardPoint = S.walkTowardPoint
local clearPointRoute = S.clearPointRoute
local resetPursuitPath = S.resetPursuitPath

-- =========================================================================
-- PATH EDITOR: fly the camera, click the map to drop ordered waypoints, and
-- reorder them in a small panel. Waypoints are plain world coordinates saved to
-- the config; the bot walks them (followPath) whenever it has nothing to fight,
-- and walks the nearest stretch of them to get out when it is wedged (recovery).
-- =========================================================================

-- In-world markers, one record per waypoint index: { orb, link, sphere }.
-- Built once per edit; passing a waypoint destroys just that record (2.1.0).
-- The old renderer destroyed and rebuilt every marker on the path each time a
-- single waypoint was passed - with Show Radius on that was a hundred-plus
-- Instances per crossing.

local function ensurePathFolder()
    if NAV.pathFolder and NAV.pathFolder.Parent then return NAV.pathFolder end
    local folder = Instance.new("Folder")
    folder.Name = "PathWaypoints"
    folder.Parent = getVisualRoot()
    NAV.pathFolder = folder
    table.clear(NAV.pathMarkers)
    return folder
end

local function destroyMarker(i)
    local marker = NAV.pathMarkers[i]
    if not marker then return end
    if marker.orb then marker.orb:Destroy() end
    if marker.link then marker.link:Destroy() end
    if marker.sphere then marker.sphere:Destroy() end
    NAV.pathMarkers[i] = nil
end

local function buildMarker(folder, i, withLink)
    local pos = NAV.waypath[i]
    local marker = {}

    if NAV.showRadius then
        local sphere = Instance.new("Part")
        sphere.Name = "Radius_" .. i
        sphere.Shape = Enum.PartType.Ball
        sphere.Size = Vector3.new(CFG.waypointClearRadius * 2, CFG.waypointClearRadius * 2,
            CFG.waypointClearRadius * 2)
        sphere.Position = pos
        sphere.Anchored = true
        sphere.CanCollide = false
        sphere.CanQuery = false
        sphere.CanTouch = false
        sphere.CastShadow = false
        sphere.Material = Enum.Material.ForceField
        sphere.Color = Color3.fromRGB(90, 190, 255)
        sphere.Transparency = 0.7
        sphere.Parent = folder
        marker.sphere = sphere
    end

    local orb = Instance.new("Part")
    orb.Name = "Waypoint_" .. i
    orb.Shape = Enum.PartType.Ball
    orb.Size = Vector3.new(1.6, 1.6, 1.6)
    orb.Position = pos
    orb.Anchored = true
    orb.CanCollide = false
    orb.CanQuery = false          -- invisible to our own raycasts
    orb.CanTouch = false
    orb.CastShadow = false
    orb.Material = Enum.Material.Neon
    orb.Color = CFG.colorWaypoint
    orb.Transparency = 0.25
    orb.Parent = folder
    marker.orb = orb

    local billboard = Instance.new("BillboardGui")
    billboard.Name = "Label"
    billboard.Size = UDim2.fromOffset(46, 26)
    billboard.StudsOffsetWorldSpace = Vector3.new(0, 2.4, 0)
    billboard.AlwaysOnTop = true
    billboard.Adornee = orb
    billboard.Parent = orb

    local label = Instance.new("TextLabel")
    label.Size = UDim2.fromScale(1, 1)
    label.BackgroundTransparency = 1
    label.Font = Enum.Font.GothamBold
    label.Text = "#" .. i
    label.TextColor3 = CFG.colorWaypoint
    label.TextStrokeTransparency = 0.2
    label.TextScaled = true
    label.Parent = billboard

    -- A faint line to the previous waypoint (only if it is also still live).
    if withLink and NAV.waypath[i - 1] then
        local prev = NAV.waypath[i - 1]
        local mid = prev:Lerp(pos, 0.5)
        local link = Instance.new("Part")
        link.Name = "Link_" .. i
        link.Anchored = true
        link.CanCollide = false
        link.CanQuery = false
        link.CanTouch = false
        link.CastShadow = false
        link.Material = Enum.Material.Neon
        link.Color = CFG.colorWaypoint
        link.Transparency = 0.6
        link.Size = Vector3.new(0.15, 0.15, (pos - prev).Magnitude)
        link.CFrame = CFrame.lookAt(mid, pos)
        link.Parent = folder
        marker.link = link
    end

    NAV.pathMarkers[i] = marker
end

-- Full rebuild: every live waypoint (index >= pathIndex) gets a marker. Used
-- when the list itself changes, on load, on a loop wrap, and when the radius
-- overlay is toggled or resized - never per frame and never on progression.
local function renderPathMarkers()
    if NAV.pathFolder then NAV.pathFolder:Destroy() end
    NAV.pathFolder = nil
    table.clear(NAV.pathMarkers)
    if #NAV.waypath == 0 then return end

    local folder = ensurePathFolder()
    for i = 1, #NAV.waypath do
        if i >= NAV.pathIndex then
            buildMarker(folder, i, i > NAV.pathIndex)
        end
    end
end

-- Incremental: drop the markers of waypoints now behind pathIndex, and the link
-- leading into the first live one. Touches only what changed.
local function refreshPathMarkers()
    local first = NAV.pathIndex
    local stale = nil
    for i in pairs(NAV.pathMarkers) do
        if i < first then
            stale = stale or {}
            stale[#stale + 1] = i
        end
    end
    if stale then
        for _, i in ipairs(stale) do destroyMarker(i) end
    end
    local marker = NAV.pathMarkers[first]
    if marker and marker.link then
        marker.link:Destroy()
        marker.link = nil
    end
end

-- refreshPathPanel is late-bound: the UI module assigns S.refreshPathPanel.

local function addWaypoint(pos)
    table.insert(NAV.waypath, pos)
    renderPathMarkers()
    if S.refreshPathPanel then S.refreshPathPanel() end
    heavyDebug("Path", string.format("Added waypoint #%d at (%.0f, %.0f, %.0f).",
        #NAV.waypath, pos.X, pos.Y, pos.Z))
end

local function removeWaypoint(index)
    if not NAV.waypath[index] then return end
    table.remove(NAV.waypath, index)
    if NAV.pathIndex > #NAV.waypath then NAV.pathIndex = 1 end
    renderPathMarkers()
    if S.refreshPathPanel then S.refreshPathPanel() end
end

local function moveWaypoint(index, delta)
    local target = index + delta
    if not NAV.waypath[index] or not NAV.waypath[target] then return end
    NAV.waypath[index], NAV.waypath[target] = NAV.waypath[target], NAV.waypath[index]
    renderPathMarkers()
    if S.refreshPathPanel then S.refreshPathPanel() end
end

local function clearWaypath()
    table.clear(NAV.waypath)
    NAV.pathIndex = 1
    renderPathMarkers()
    if S.refreshPathPanel then S.refreshPathPanel() end
end

-- Called every frame: as the player passes within the clear radius of the NEXT
-- waypoint in order, that waypoint is marked passed and its marker clears. Only
-- the next one in sequence is ever consumed (chronological), and NAV.waypath -
-- the saved list - is never touched, so the config stays permanent.
local function progressPath(rootPos)
    -- Recovery drives pathIndex itself while it is walking the path.
    if NAV.recovery then return end
    local count = #NAV.waypath
    if count == 0 or NAV.pathIndex > count then return end
    if NAV.pathIndex < 1 then NAV.pathIndex = 1 end

    local passed = false
    while NAV.pathIndex <= count
        and (rootPos - NAV.waypath[NAV.pathIndex]).Magnitude <= CFG.waypointClearRadius do
        NAV.pathIndex = NAV.pathIndex + 1
        passed = true
    end

    if passed then
        clearPointRoute()
        if NAV.pathIndex > count and CFG.loopPath then
            NAV.pathIndex = 1
            renderPathMarkers()
        else
            refreshPathMarkers()
        end
    end
end

-- =========================================================================
-- RECOVERY (2.2.0): the manual path as the last resort.
--
-- Normal navigation - navmesh, the retry ladder, direct steering, the heading
-- and area blacklists - is what gets the bot to enemies. When all of it has
-- still left the character loitering in one spot, the one thing that is known
-- to be walkable is the path the user laid down by hand. Recovery walks to the
-- nearest waypoint (routed, see walkTowardPoint) and on along the path for a
-- couple of points, then hands back to pursuit with a clean slate. Re-sticking
-- soon after continues further along the path instead of returning to the
-- same nearest point, and each repeat walks a longer stretch.
-- =========================================================================

local function nearestWaypointIndex(position)
    local best, bestScore = nil, math.huge
    for i, p in ipairs(NAV.waypath) do
        local score = Vector3.new(p.X - position.X, 0, p.Z - position.Z).Magnitude
        -- A waypoint well above us (a ledge overhead) is not a way out from here.
        if p.Y - position.Y > CFG.maxClimbHeight then score = score + 40 end
        if score < bestScore then best, bestScore = i, score end
    end
    return best
end

local function exitRecovery(reason)
    local recovery = NAV.recovery
    if not recovery then return end
    NAV.recovery = nil
    NAV.lastRecoveryEnd = os.clock()
    NAV.lastRecoveryIndex = recovery.index
    NAV.stuckAnchor = nil
    clearPointRoute()
    resetPursuitPath()
    -- The wedge is behind us: let pursuit retry everything it had given up on.
    table.clear(NAV.benched)
    NAV.forceRescan = true
    heavyDebug("Recovery", string.format(
        "Recovery over (%s) after %.1fs; back to normal navigation at path #%d.",
        reason, os.clock() - recovery.startedAt, recovery.index))
end

local function enterRecovery(root, reason)
    if not CFG.recoveryEnabled or NAV.recovery then return false end
    if #NAV.waypath == 0 then
        heavyDebugThrottled("recovery_nopath", 10.0, "Recovery",
            "Stuck (" .. reason .. ") but no manual path is set, so there is nothing to recover along. Lay one down in Edit Path.")
        return false
    end

    local now = os.clock()
    local remaining = CFG.recoveryWaypoints
    local index
    if NAV.lastRecoveryIndex and NAV.waypath[NAV.lastRecoveryIndex]
        and now - NAV.lastRecoveryEnd <= CFG.recoveryRepeatWindow then
        -- Stuck again right after a recovery: the nearest waypoint is probably
        -- the one we just walked back from. Continue along the path instead,
        -- and further this time.
        index = NAV.lastRecoveryIndex
        remaining = remaining + CFG.recoveryEscalation
    else
        index = nearestWaypointIndex(root.Position)
    end
    -- Walking to a waypoint we are already standing on achieves nothing.
    if (NAV.waypath[index] - root.Position).Magnitude <= CFG.recoveryArriveRadius then
        index = index + 1
        if index > #NAV.waypath then
            index = CFG.loopPath and 1 or #NAV.waypath
        end
    end

    NAV.recovery = {
        index = index,
        remaining = remaining,
        deadline = now + CFG.recoveryMaxTime,
        startedAt = now,
        stuckAt = root.Position,
    }
    NAV.pathIndex = index
    renderPathMarkers()
    clearPointRoute()
    resetPursuitPath()
    NAV.stuckAnchor = nil
    heavyDebug("Recovery", string.format(
        "STUCK (%s) at (%.0f, %.0f, %.0f). Walking the manual path from #%d for %d waypoint(s).",
        reason, root.Position.X, root.Position.Y, root.Position.Z, index, remaining))
    setMovementState(string.format("RECOVERY: to path #%d", index))
    return true
end

-- The recovery branch of the main loop. Returns false once recovery has ended.
local function runRecovery(humanoid, root)
    local recovery = NAV.recovery
    if not recovery then return false end
    local now = os.clock()

    local target = NAV.waypath[recovery.index]
    if not target then
        exitRecovery("ran out of path")
        return false
    end
    if now > recovery.deadline then
        exitRecovery("time limit")
        return false
    end

    -- A mob in our face is not a wedge; fight it.
    local enemy = NAV.cachedEnemy
    if enemy then
        local enemyRoot = enemy:FindFirstChild("HumanoidRootPart") or enemy.PrimaryPart
        if enemyRoot and (enemyRoot.Position - root.Position).Magnitude <= CFG.attackRange then
            exitRecovery("enemy in reach")
            return false
        end
    end

    local distance, stuck = walkTowardPoint(humanoid, root, target)
    if distance <= CFG.recoveryArriveRadius or stuck then
        if stuck then
            heavyDebug("Recovery", string.format(
                "Path #%d not getting closer for %.0fs; skipping it.", recovery.index, CFG.pointGiveUpTime))
        end
        recovery.index = recovery.index + 1
        if recovery.index > #NAV.waypath then
            if CFG.loopPath then
                recovery.index = 1
            else
                exitRecovery("end of path")
                return false
            end
        end
        recovery.remaining = recovery.remaining - 1
        NAV.pathIndex = recovery.index
        refreshPathMarkers()
        clearPointRoute()
        if recovery.remaining <= 0 then
            exitRecovery("walked the segment")
            return false
        end
    end

    setMovementState(string.format("RECOVERY wp #%d (%.0f studs, %d to go)",
        recovery.index, distance, recovery.remaining))
    return true
end

-- Stuck detector, called once per frame by the main loop AFTER the branch ran,
-- so `driving` reflects this frame. Loitering inside recoveryStuckRadius for
-- recoveryStuckTime while actively trying to move means the normal navigation
-- has wedged itself. Not armed while dodging (holding still inside a
-- telegraph's clearance is the escape logic working) or while standing in
-- range attacking (that is not moving on purpose).
local function updateStuckDetector(root, driving, inHazard, now)
    if NAV.recovery or not driving or inHazard then
        NAV.stuckAnchor = nil
        return false
    end
    if not NAV.stuckAnchor
        or (root.Position - NAV.stuckAnchor).Magnitude > CFG.recoveryStuckRadius then
        NAV.stuckAnchor = root.Position
        NAV.stuckAnchorTime = now
        return false
    end
    if now - NAV.stuckAnchorTime >= CFG.recoveryStuckTime then
        NAV.stuckAnchor = nil
        return enterRecovery(root, string.format(
            "within %.0f studs for %.1fs", CFG.recoveryStuckRadius, CFG.recoveryStuckTime))
    end
    return false
end

-- Free-fly camera + click-to-place. While armed: hold RIGHT mouse to look, WASD
-- to fly (E/Q up/down), and LEFT-click a spot on the map to drop a waypoint there.
local function setPathEditEnabled(enabled)
    for _, connection in ipairs(NAV.pathEditConnections) do
        connection:Disconnect()
    end
    table.clear(NAV.pathEditConnections)
    NAV.pathEditEnabled = enabled

    local camera = Workspace.CurrentCamera
    if not enabled then
        if camera and NAV.savedCameraType then
            camera.CameraType = NAV.savedCameraType
        elseif camera then
            camera.CameraType = Enum.CameraType.Custom
        end
        table.clear(NAV.freecamKeys)
        NAV.freecamLooking = false
        pcall(function() UserInputService.MouseBehavior = Enum.MouseBehavior.Default end)
        setMovementState("path editor off")
        return
    end

    if not camera then return end
    NAV.savedCameraType = camera.CameraType
    camera.CameraType = Enum.CameraType.Scriptable
    NAV.freecamCFrame = camera.CFrame
    local _, y, _ = camera.CFrame:ToOrientation()
    NAV.freecamYaw = y
    NAV.freecamPitch = 0
    table.clear(NAV.freecamKeys)
    NAV.freecamLooking = false

    local KEY_VECTORS = {
        [Enum.KeyCode.W] = Vector3.new(0, 0, -1),
        [Enum.KeyCode.S] = Vector3.new(0, 0, 1),
        [Enum.KeyCode.A] = Vector3.new(-1, 0, 0),
        [Enum.KeyCode.D] = Vector3.new(1, 0, 0),
        [Enum.KeyCode.E] = Vector3.new(0, 1, 0),
        [Enum.KeyCode.Q] = Vector3.new(0, -1, 0),
    }

    table.insert(NAV.pathEditConnections, UserInputService.InputBegan:Connect(function(input, processed)
        if processed then return end
        if KEY_VECTORS[input.KeyCode] then
            NAV.freecamKeys[input.KeyCode] = true
        elseif input.UserInputType == Enum.UserInputType.MouseButton2 then
            NAV.freecamLooking = true
            -- Pin the cursor so the look delta keeps coming instead of stopping
            -- dead the moment the pointer reaches a screen edge.
            pcall(function()
                UserInputService.MouseBehavior = Enum.MouseBehavior.LockCurrentPosition
            end)
        elseif input.UserInputType == Enum.UserInputType.MouseButton1 then
            -- Drop a waypoint where the cursor is pointing on the map.
            local mouse = LocalPlayer:GetMouse()
            local hit = mouse.Hit
            if hit then addWaypoint(hit.Position) end
        end
    end))

    table.insert(NAV.pathEditConnections, UserInputService.InputEnded:Connect(function(input)
        if KEY_VECTORS[input.KeyCode] then
            NAV.freecamKeys[input.KeyCode] = nil
        elseif input.UserInputType == Enum.UserInputType.MouseButton2 then
            NAV.freecamLooking = false
            pcall(function()
                UserInputService.MouseBehavior = Enum.MouseBehavior.Default
            end)
        end
    end))

    table.insert(NAV.pathEditConnections, UserInputService.InputChanged:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseMovement and NAV.freecamLooking then
            local s = math.rad(CFG.freecamLookSensitivity)
            NAV.freecamYaw = NAV.freecamYaw - input.Delta.X * s
            NAV.freecamPitch = math.clamp(NAV.freecamPitch - input.Delta.Y * s,
                math.rad(-89), math.rad(89))
        end
    end))

    table.insert(NAV.pathEditConnections, RunService.RenderStepped:Connect(function(dt)
        local cam = Workspace.CurrentCamera
        if not cam or not NAV.pathEditEnabled then return end
        local rot = CFrame.Angles(0, NAV.freecamYaw, 0) * CFrame.Angles(NAV.freecamPitch, 0, 0)
        local move = Vector3.zero
        for key, vec in pairs(KEY_VECTORS) do
            if NAV.freecamKeys[key] then move = move + vec end
        end
        local pos = NAV.freecamCFrame.Position
        if move.Magnitude > 0 then
            pos = pos + (rot:VectorToWorldSpace(move.Unit) * CFG.freecamSpeed * dt)
        end
        NAV.freecamCFrame = CFrame.new(pos) * rot
        cam.CFrame = NAV.freecamCFrame
    end))

    setMovementState("path editor: fly (WASD/EQ), right-drag look, left-click to place")
    heavyDebug("Path", "Path editor armed. WASD+EQ fly, hold right mouse to look, left-click places a waypoint.")
end

S.clearWaypath = clearWaypath
S.moveWaypoint = moveWaypoint
S.progressPath = progressPath
S.removeWaypoint = removeWaypoint
S.renderPathMarkers = renderPathMarkers
S.refreshPathMarkers = refreshPathMarkers
S.setPathEditEnabled = setPathEditEnabled
S.enterRecovery = enterRecovery
S.exitRecovery = exitRecovery
S.runRecovery = runRecovery
S.updateStuckDetector = updateStuckDetector
end
    end)()
    module(S)
end

-- ===================================== src/streamer.lua =====================================
do
    local module = (function()
-- streamer.lua - Streamer Mode: local cosmetic masking of the account identity.
-- Module contract: receives the shared table S. Everything this module needs from
-- earlier modules is pulled into locals below; everything later modules need is
-- assigned onto S at the bottom. Load order is fixed by main.lua / build.py.
return function(S)
local RT = S.RT
local SM = S.SM
local heavyDebug = S.heavyDebug
local LocalPlayer = S.LocalPlayer
local RunService = S.RunService
local heavyDebugThrottled = S.heavyDebugThrottled
local UserInputService = S.UserInputService
local SCRIPT_VERSION = S.SCRIPT_VERSION

--[[ ===========================================================================
    STREAMER MODE

    Local cosmetic overlay for streaming: masks the account identity on screen.
    It rewrites what THIS client renders, nothing else. The server, other
    players, and every leaderboard still see the real account, so this hides
    your name on stream, it does not change your name in the game.

    The game's GUI hierarchy is unknown to this script, so targets are found by
    content rather than by path: any text showing the real username or display
    name is rewritten, any image sourced from the real user id is swapped. HP,
    EXP, level and VIP fields are matched by name keywords, and anything the
    keywords miss can be bound by hand with the row's bind button.
=========================================================================== ]]

SM.enabled = false
SM.connection = nil
SM.bindConnection = nil
SM.panel = nil
SM.statusLabel = nil

SM.fields = {
    username = "Streamer",
    hp = "",
    vipTitle = "",
    exp = "",
    level = "",
    coins = "",
    gems = "",
}

SM.vipColor = Color3.fromRGB(255, 200, 60)
SM.borderColor = Color3.fromRGB(255, 200, 60)
SM.levelColor = Color3.fromRGB(120, 190, 255)
SM.avatarImage = ""

-- [field] = { [instance] = true }. Populated by auto-detection and by binds.
SM.targets = {
    username = {},
    hp = {},
    vipTitle = {},
    exp = {},
    level = {},
    coins = {},
    gems = {},
    border = {},
    avatar = {},
}

SM.manualBinds = {}
SM.originals = {}
SM.pendingBindField = nil
SM.lastDiscoveryTime = -math.huge
SM.discoveryInterval = 1.5
SM.applyInterval = 0.12
SM.lastApplyTime = -math.huge

-- Text that identifies a developer/telemetry overlay worth hiding on stream.
-- A container is hidden when at least two of these appear beneath it, so a
-- single label that merely mentions "position" is not enough to trigger it.
SM.debugOverlayPhrases = {
    "world position", "data loaded", "place version", "server age",
    "server region", "job id", "jobid", "instance id", "session id",
    "client version", "build id", "user id", "userid", "account age",
}

SM.hiddenElements = {}
SM.autoHideOverlays = true

-- [instance] = { connections } watching Text/Image so an override is reasserted
-- the instant the game writes, rather than on the next poll.
SM.signalConnections = {}
-- Set by the panel so a config-driven enable can update the toggle's own label.
SM.syncToggleWidget = nil
-- Re-entrancy guard: writing Text refires the same signal we are handling.
SM.applyingTo = {}

-- Forward declaration; defined once applyBorderColorTo is available.
local applyToTarget

SM.fieldKeywords = {
    hp = { "hp", "health", "hitpoint" },
    exp = { "exp", "xp", "experience" },
    level = { "level", "lvl", "rank" },
    vipTitle = { "vip", "title", "tag", "premium", "badge" },
    coins = { "coin", "gold", "cash", "money", "currency" },
    gems = { "gem", "diamond", "crystal", "robux" },
}

local function parseHexColor(text)
    if type(text) ~= "string" then return nil end
    local hex = text:gsub("#", ""):gsub("%s", "")
    if #hex ~= 6 then return nil end
    local r = tonumber(hex:sub(1, 2), 16)
    local g = tonumber(hex:sub(3, 4), 16)
    local b = tonumber(hex:sub(5, 6), 16)
    if not r or not g or not b then return nil end
    return Color3.fromRGB(r, g, b)
end

local function toHexString(color)
    return string.format("%02X%02X%02X",
        math.floor(color.R * 255 + 0.5),
        math.floor(color.G * 255 + 0.5),
        math.floor(color.B * 255 + 0.5))
end

-- Roblox cannot upload an image from a script. Accepts an asset id, an
-- rbxassetid:// string, or a roblox.com URL, and normalises to rbxassetid://.
local function normalizeImageId(text)
    if type(text) ~= "string" then return "" end
    local digits = text:match("(%d+)")
    if not digits then return "" end
    return "rbxassetid://" .. digits
end

local function isTextObject(obj)
    return obj:IsA("TextLabel") or obj:IsA("TextButton") or obj:IsA("TextBox")
end

local function isImageObject(obj)
    return obj:IsA("ImageLabel") or obj:IsA("ImageButton")
end

local function rememberStreamerOriginal(obj)
    if SM.originals[obj] then return end
    local snapshot = {}
    if isTextObject(obj) then
        snapshot.Text = obj.Text
        snapshot.TextColor3 = obj.TextColor3
    end
    if isImageObject(obj) then
        snapshot.Image = obj.Image
        snapshot.ImageColor3 = obj.ImageColor3
    end
    if obj:IsA("UIStroke") then
        snapshot.StrokeColor = obj.Color
    end
    if obj:IsA("GuiObject") then
        snapshot.BorderColor3 = obj.BorderColor3
        snapshot.BackgroundColor3 = obj.BackgroundColor3
    end
    SM.originals[obj] = snapshot
end

-- Registers a target and starts watching it. The watch is what removes the
-- flicker: polling every 0.12s meant the game's own write (on an EXP tick, a
-- damage number, a stat refresh) was visible until the next poll came round.
-- Reacting to the property signal puts the correction in the same frame.
local function registerStreamerTarget(field, obj)
    local set = SM.targets[field]
    if not set or set[obj] then return end

    set[obj] = true
    rememberStreamerOriginal(obj)

    if not SM.signalConnections[obj] then
        local connections = {}

        local function watch(property)
            local ok, signal = pcall(function()
                return obj:GetPropertyChangedSignal(property)
            end)
            if ok and signal then
                table.insert(connections, signal:Connect(function()
                    if SM.enabled then
                        applyToTarget(field, obj)
                    end
                end))
            end
        end

        if isTextObject(obj) then watch("Text") end
        if isImageObject(obj) then watch("Image") end

        SM.signalConnections[obj] = connections
    end

    if SM.enabled then
        applyToTarget(field, obj)
    end
end

local function unwatchStreamerTarget(obj)
    local connections = SM.signalConnections[obj]
    if not connections then return end
    for _, connection in ipairs(connections) do
        connection:Disconnect()
    end
    SM.signalConnections[obj] = nil
end

local function unwatchAllStreamerTargets()
    for obj in pairs(SM.signalConnections) do
        unwatchStreamerTarget(obj)
    end
    table.clear(SM.signalConnections)
    table.clear(SM.applyingTo)
end

-- Most nametags draw their "border" as a gold Frame sitting behind a slightly
-- smaller inner Frame, not as a UIStroke. Detecting by class alone therefore
-- missed it entirely, so trim is identified by colour instead: warm golds and
-- yellows, where red and green are both strong and clearly above blue.
-- The green HP fill, the cream badge backing and dark panels all fail this.
local function isTrimColor(color)
    return color.R >= 0.55
        and color.G >= 0.38
        and color.B <= 0.55
        and color.R >= color.G
        and (color.G - color.B) >= 0.15
end

-- Collects the trim pieces of any nametag billboard in `container`. Scoped to
-- billboards so a gold element elsewhere in the HUD is never repainted.
local function collectNametagTrim(container, character)
    for _, obj in ipairs(container:GetDescendants()) do
        local billboard = obj:FindFirstAncestorOfClass("BillboardGui")
        if billboard then
            -- Billboards living outside the character only count when they are
            -- adorned to it, so other players' nametags are left alone.
            local ownsIt = character and (billboard:IsDescendantOf(character)
                or (billboard.Adornee and billboard.Adornee:IsDescendantOf(character)))

            if ownsIt then
                local isTrim = false

                if obj:IsA("UIStroke") then
                    isTrim = true
                elseif obj:IsA("GuiObject") and not isTextObject(obj) then
                    if obj.BackgroundTransparency < 0.95 and isTrimColor(obj.BackgroundColor3) then
                        isTrim = true
                    elseif isImageObject(obj) and obj.ImageTransparency < 0.95 and isTrimColor(obj.ImageColor3) then
                        isTrim = true
                    end
                end

                if isTrim then
                    registerStreamerTarget("border", obj)
                end
            end
        end
    end
end

-- The gold trim on the nametag can be a UIStroke, a bordered frame, or a plain
-- coloured backing frame depending on how the game built it, so all three are
-- handled and the most specific one wins.
local function applyBorderColorTo(obj, color)
    if obj:IsA("UIStroke") then
        obj.Color = color
        return
    end

    -- Ordered so the property that is actually drawing the trim wins. A visible
    -- background is what the colour detection matched on, so it takes priority
    -- over a stroke the element may also happen to carry.
    if isImageObject(obj) and obj.Image ~= "" and obj.ImageTransparency < 0.95 then
        obj.ImageColor3 = color
        return
    end

    if obj:IsA("GuiObject") then
        if obj.BackgroundTransparency < 0.95 then
            obj.BackgroundColor3 = color
            return
        end
        if obj.BorderSizePixel > 0 then
            obj.BorderColor3 = color
            return
        end
        local stroke = obj:FindFirstChildOfClass("UIStroke")
        if stroke then
            rememberStreamerOriginal(stroke)
            stroke.Color = color
        end
    end
end

local function nameMatchesKeywords(obj, keywords)
    local node = obj
    local depth = 0
    while node and depth < 4 do
        local lowered = string.lower(node.Name)
        for _, word in ipairs(keywords) do
            if string.find(lowered, word, 1, true) then
                return true
            end
        end
        node = node.Parent
        depth = depth + 1
    end
    return false
end

-- Targets are sticky: only destroyed instances are dropped. Detection is by
-- content, so a label already showing the fake name no longer matches the real
-- one; forgetting it would let the real name flash back for up to one discovery
-- interval whenever the game rewrote that label.
local function pruneDeadStreamerTargets()
    for obj in pairs(SM.hiddenElements) do
        if not obj.Parent then
            SM.hiddenElements[obj] = nil
        end
    end

    for _, set in pairs(SM.targets) do
        for obj in pairs(set) do
            if not obj.Parent then
                set[obj] = nil
                SM.originals[obj] = nil
                SM.manualBinds[obj] = nil
                unwatchStreamerTarget(obj)
            end
        end
    end
end

local function scanContainerForStreamerTargets(container, realName, realDisplay, realUserId)
    for _, obj in ipairs(container:GetDescendants()) do
        local isOurs = RT.scriptGui and obj:IsDescendantOf(RT.scriptGui)
        if not isOurs then
            if isTextObject(obj) then
                local text = obj.Text
                if text ~= "" then
                    if string.find(text, realName, 1, true)
                        or (realDisplay ~= realName and string.find(text, realDisplay, 1, true)) then
                        registerStreamerTarget("username", obj)
                    end

                    for field, keywords in pairs(SM.fieldKeywords) do
                        if SM.fields[field] ~= "" and nameMatchesKeywords(obj, keywords) then
                            registerStreamerTarget(field, obj)
                        end
                    end
                end
            elseif isImageObject(obj) then
                if string.find(obj.Image, realUserId, 1, true) then
                    registerStreamerTarget("avatar", obj)
                end
            end
        end
    end
end

local function hideStreamerElement(obj, reason)
    if not obj or SM.hiddenElements[obj] then return end
    if RT.scriptGui and obj:IsDescendantOf(RT.scriptGui) then return end
    if not obj:IsA("GuiObject") then return end

    SM.hiddenElements[obj] = obj.Visible
    obj.Visible = false
    heavyDebug("Streamer", string.format("Hid '%s' (%s) - %s", obj.Name, obj.ClassName, reason))
end

local function restoreHiddenElements()
    for obj, wasVisible in pairs(SM.hiddenElements) do
        if obj.Parent then
            pcall(function() obj.Visible = wasVisible end)
        end
    end
    table.clear(SM.hiddenElements)
end

-- Finds telemetry overlays like the World Position / Data Loaded / Place Version
-- / Server Age readout and hides the container holding them, rather than each
-- row, so no empty frame is left behind.
local function hideDebugOverlays(playerGui)
    if not SM.autoHideOverlays then return end

    local matchCounts = {}

    for _, obj in ipairs(playerGui:GetDescendants()) do
        local isOurs = RT.scriptGui and obj:IsDescendantOf(RT.scriptGui)
        if not isOurs and isTextObject(obj) and obj.Text ~= "" then
            local lowered = string.lower(obj.Text)
            local matched = false
            for _, phrase in ipairs(SM.debugOverlayPhrases) do
                if string.find(lowered, phrase, 1, true) then
                    matched = true
                    break
                end
            end

            if matched then
                -- Credit the label and its nearby ancestors, so the shared
                -- container accumulates the highest count.
                local node = obj
                local depth = 0
                while node and depth < 5 and not node:IsA("ScreenGui") do
                    matchCounts[node] = (matchCounts[node] or 0) + 1
                    node = node.Parent
                    depth = depth + 1
                end
            end
        end
    end

    for node, count in pairs(matchCounts) do
        if count >= 2 and node:IsA("GuiObject") then
            -- Hide the outermost container that still holds every match, so the
            -- whole readout goes at once.
            local best = node
            local walker = node.Parent
            local depth = 0
            while walker and depth < 4 and walker:IsA("GuiObject") do
                if (matchCounts[walker] or 0) == count then
                    best = walker
                end
                walker = walker.Parent
                depth = depth + 1
            end
            hideStreamerElement(best, string.format("telemetry overlay, %d matches", count))
        end
    end
end

-- Applies one field to one element. Split out of the bulk apply so a property
-- signal can correct a single label immediately without sweeping everything.
applyToTarget = function(field, obj)
    if not obj.Parent or SM.applyingTo[obj] then return end
    SM.applyingTo[obj] = true

    if field == "border" then
        applyBorderColorTo(obj, SM.borderColor)

    elseif field == "avatar" then
        if SM.avatarImage ~= "" and isImageObject(obj) and obj.Image ~= SM.avatarImage then
            obj.Image = SM.avatarImage
        end

    elseif field == "username" then
        if isTextObject(obj) then
            local realName = LocalPlayer.Name
            local realDisplay = LocalPlayer.DisplayName or realName
            local fakeName = SM.fields.username ~= "" and SM.fields.username or "Streamer"
            local current = obj.Text
            local replaced = string.gsub(current, realName, fakeName)
            if realDisplay ~= realName then
                replaced = string.gsub(replaced, realDisplay, fakeName)
            end
            if replaced ~= current then
                obj.Text = replaced
            end
        end

    else
        local value = SM.fields[field]
        if value and value ~= "" and isTextObject(obj) then
            if obj.Text ~= value then
                obj.Text = value
            end
            if field == "vipTitle" then
                obj.TextColor3 = SM.vipColor
            elseif field == "level" then
                obj.TextColor3 = SM.levelColor
            end
        end
    end

    SM.applyingTo[obj] = nil
end

-- Full path from the DataModel, so a reported element can be located exactly.
local function describeInstancePath(obj)
    local segments = {}
    local node = obj
    local depth = 0
    while node and node ~= game and depth < 12 do
        table.insert(segments, 1, node.Name)
        node = node.Parent
        depth = depth + 1
    end
    return table.concat(segments, ".")
end

-- Prints every GUI element that looks identity-bearing, with its path, class and
-- current text. Run it, copy the console, and the matching rules can be widened
-- to whatever this particular game actually uses.
local function dumpStreamerCandidates()
    local realName = LocalPlayer.Name
    local realDisplay = LocalPlayer.DisplayName or realName
    local realUserId = tostring(LocalPlayer.UserId)

    print(string.rep("=", 78))
    print(string.format("  STREAMER GUI DUMP  |  v%s  |  account: %s (display '%s', id %s)",
        SCRIPT_VERSION, realName, realDisplay, realUserId))
    print(string.rep("=", 78))

    local total = 0

    local function dumpContainer(container, containerLabel)
        if not container then return end
        print(string.format("--- %s ---", containerLabel))
        local found = 0

        for _, obj in ipairs(container:GetDescendants()) do
            local isOurs = RT.scriptGui and obj:IsDescendantOf(RT.scriptGui)
            if not isOurs then
                local reasons = nil

                local function note(tag)
                    reasons = reasons or {}
                    table.insert(reasons, tag)
                end

                if isTextObject(obj) and obj.Text ~= "" then
                    local text = obj.Text
                    local lowered = string.lower(text)

                    if string.find(text, realName, 1, true) then note("USERNAME") end
                    if realDisplay ~= realName and string.find(text, realDisplay, 1, true) then note("DISPLAYNAME") end
                    -- Value shapes visible in the HUD: "5.30M/5.30M", "129.84M/3.69B",
                    -- "5307855/5307855", a bare level number, and VIP/title text.
                    if string.match(text, "^%s*[%d%.,]+[KMBT]?%s*/%s*[%d%.,]+[KMBT]?%s*$") then note("PAIR_VALUE") end
                    if string.match(text, "^%s*%d+%s*$") then note("BARE_NUMBER") end
                    if string.find(lowered, "hp", 1, true) or string.find(lowered, "health", 1, true) then note("HP_TEXT") end
                    if string.find(lowered, "exp", 1, true) then note("EXP_TEXT") end
                    if string.find(lowered, "vip", 1, true) then note("VIP_TEXT") end
                    if string.match(text, "^%s*%b()%s*$") then note("PARENTHESISED") end

                    for field, keywords in pairs(SM.fieldKeywords) do
                        if nameMatchesKeywords(obj, keywords) then note("NAMEHINT:" .. field) end
                    end

                    if reasons then
                        found = found + 1
                        total = total + 1
                        print(string.format("[%s] %s", table.concat(reasons, ","), obj.ClassName))
                        print(string.format("    text : %q", text))
                        print(string.format("    path : %s", describeInstancePath(obj)))
                    end
                elseif isImageObject(obj) and obj.Image ~= "" then
                    if string.find(obj.Image, realUserId, 1, true) then
                        found = found + 1
                        total = total + 1
                        print(string.format("[AVATAR] %s", obj.ClassName))
                        print(string.format("    image: %s", obj.Image))
                        print(string.format("    path : %s", describeInstancePath(obj)))
                    end
                end
            end
        end

        if found == 0 then
            print("  (nothing matched here)")
        end
    end

    dumpContainer(LocalPlayer:FindFirstChildOfClass("PlayerGui"), "PlayerGui")
    dumpContainer(LocalPlayer.Character, "Character (nametag billboards)")

    print("--- nametag trim currently detected ---")
    local trimCount = 0
    for obj in pairs(SM.targets.border) do
        if obj.Parent then
            trimCount = trimCount + 1
            local swatch
            if obj:IsA("UIStroke") then
                swatch = "stroke " .. toHexString(obj.Color)
            elseif isImageObject(obj) and obj.Image ~= "" and obj.ImageTransparency < 0.95 then
                swatch = "image tint " .. toHexString(obj.ImageColor3)
            elseif obj:IsA("GuiObject") and obj.BackgroundTransparency < 0.95 then
                swatch = "background " .. toHexString(obj.BackgroundColor3)
            else
                swatch = "border " .. toHexString(obj.BorderColor3)
            end
            print(string.format("[TRIM] %s (%s)", obj.ClassName, swatch))
            print(string.format("    path : %s", describeInstancePath(obj)))
        end
    end
    if trimCount == 0 then
        print("  (none detected - use the trim row's bind button and click the border)")
    end

    print(string.rep("=", 78))
    print(string.format("  %d candidate elements, %d trim pieces.", total, trimCount))
    print(string.rep("=", 78))

    return total
end

local function discoverStreamerTargets()
    local realName = LocalPlayer.Name
    local realDisplay = LocalPlayer.DisplayName or realName
    local realUserId = tostring(LocalPlayer.UserId)

    pruneDeadStreamerTargets()

    local playerGui = LocalPlayer:FindFirstChildOfClass("PlayerGui")
    if playerGui then
        scanContainerForStreamerTargets(playerGui, realName, realDisplay, realUserId)
        hideDebugOverlays(playerGui)
    end

    -- Character descendants carry the overhead nametag billboards.
    local character = LocalPlayer.Character
    if character then
        scanContainerForStreamerTargets(character, realName, realDisplay, realUserId)

        collectNametagTrim(character, character)
    end

    -- Some games parent the nametag billboard into PlayerGui and adorn it to the
    -- head instead of nesting it under the character, so check there too. The
    -- adornee test keeps other players' nametags out of it.
    if playerGui and character then
        collectNametagTrim(playerGui, character)
    end

    for obj, field in pairs(SM.manualBinds) do
        if obj.Parent then
            registerStreamerTarget(field, obj)
        else
            SM.manualBinds[obj] = nil
        end
    end
end

local function applyStreamerOverlay()
    for field, set in pairs(SM.targets) do
        for obj in pairs(set) do
            applyToTarget(field, obj)
        end
    end
end

local function restoreStreamerOriginals()
    for obj, snapshot in pairs(SM.originals) do
        if obj.Parent then
            pcall(function()
                if snapshot.Text ~= nil and isTextObject(obj) then
                    obj.Text = snapshot.Text
                    obj.TextColor3 = snapshot.TextColor3
                end
                if snapshot.Image ~= nil and isImageObject(obj) then
                    obj.Image = snapshot.Image
                    obj.ImageColor3 = snapshot.ImageColor3
                end
                if snapshot.StrokeColor ~= nil and obj:IsA("UIStroke") then
                    obj.Color = snapshot.StrokeColor
                end
                if snapshot.BorderColor3 ~= nil and obj:IsA("GuiObject") then
                    obj.BorderColor3 = snapshot.BorderColor3
                    obj.BackgroundColor3 = snapshot.BackgroundColor3
                end
            end)
        end
    end
    table.clear(SM.originals)
end

local function setStreamerStatus(text)
    if SM.statusLabel then
        SM.statusLabel.Text = text
    end
end

local function countStreamerTargets()
    local total = 0
    for _, set in pairs(SM.targets) do
        for _ in pairs(set) do
            total = total + 1
        end
    end
    return total
end

local function setStreamerEnabled(enabled)
    SM.enabled = enabled

    if SM.connection then
        SM.connection:Disconnect()
        SM.connection = nil
    end

    if not enabled then
        unwatchAllStreamerTargets()
        restoreStreamerOriginals()
        restoreHiddenElements()
        for field in pairs(SM.targets) do
            SM.targets[field] = {}
        end
        setStreamerStatus("Off. Original display restored.")
        heavyDebug("Streamer", "Streamer mode disabled, originals restored.")
        return
    end

    discoverStreamerTargets()
    applyStreamerOverlay()
    SM.lastDiscoveryTime = os.clock()
    setStreamerStatus(string.format("On. %d elements masked.", countStreamerTargets()))
    heavyDebug("Streamer", string.format("Streamer mode enabled. %d elements masked.", countStreamerTargets()))

    -- The game rewrites its own labels, so the overlay has to be reasserted.
    -- Both clocks are deliberately slow; this is cosmetic and must not cost frames.
    SM.connection = RunService.Heartbeat:Connect(function()
        if RT.destroyed or not SM.enabled then return end
        local clock = os.clock()

        if clock - SM.lastApplyTime >= SM.applyInterval then
            SM.lastApplyTime = clock
            local ok, err = xpcall(applyStreamerOverlay, debug.traceback)
            if not ok then
                heavyDebugThrottled("streamer_apply_err", 2.0, "FATAL", "Streamer overlay threw:\n" .. tostring(err))
            end
        end

        if clock - SM.lastDiscoveryTime >= SM.discoveryInterval then
            SM.lastDiscoveryTime = clock
            local ok, err = xpcall(discoverStreamerTargets, debug.traceback)
            if not ok then
                heavyDebugThrottled("streamer_scan_err", 2.0, "FATAL", "Streamer discovery threw:\n" .. tostring(err))
            else
                setStreamerStatus(string.format("On. %d elements masked.", countStreamerTargets()))
            end
        end
    end)
end

local function refreshStreamerOverlay()
    if not SM.enabled then return end
    discoverStreamerTargets()
    applyStreamerOverlay()
    setStreamerStatus(string.format("On. %d elements masked.", countStreamerTargets()))
end

-- Bind mode: the next GUI click assigns that element to the pending field, for
-- anything the keyword matching did not find.
local function setPendingBindField(field)
    SM.pendingBindField = field

    if SM.bindConnection then
        SM.bindConnection:Disconnect()
        SM.bindConnection = nil
    end

    if not field then return end

    setStreamerStatus("Bind armed: click the " .. field .. " element on screen.")

    SM.bindConnection = UserInputService.InputBegan:Connect(function(input, processed)
        if not SM.pendingBindField then return end
        if input.UserInputType ~= Enum.UserInputType.MouseButton1
            and input.UserInputType ~= Enum.UserInputType.Touch then
            return
        end

        local playerGui = LocalPlayer:FindFirstChildOfClass("PlayerGui")
        if not playerGui then return end

        local inset = game:GetService("GuiService"):GetGuiInset()
        local position = UserInputService:GetMouseLocation()
        local candidates = playerGui:GetGuiObjectsAtPosition(position.X - inset.X, position.Y - inset.Y)

        for _, obj in ipairs(candidates) do
            local isOurs = RT.scriptGui and obj:IsDescendantOf(RT.scriptGui)
            if not isOurs and SM.pendingBindField == "hide" and obj:IsA("GuiObject") then
                hideStreamerElement(obj, "hidden by hand")
                setStreamerStatus(string.format("Hid '%s'.", obj.Name))
                setPendingBindField(nil)
                return
            end

            if not isOurs and SM.pendingBindField == "border" and obj:IsA("GuiObject") then
                SM.manualBinds[obj] = "border"
                registerStreamerTarget("border", obj)
                setStreamerStatus(string.format("Bound '%s' as nametag trim.", obj.Name))
                setPendingBindField(nil)
                applyStreamerOverlay()
                return
            end

            if not isOurs and (isTextObject(obj) or isImageObject(obj)) then
                local field = SM.pendingBindField
                SM.manualBinds[obj] = field
                registerStreamerTarget(field, obj)
                heavyDebug("Streamer", string.format("Bound '%s' (%s) to field '%s'.",
                    obj.Name, obj.ClassName, field))
                setStreamerStatus(string.format("Bound '%s' to %s.", obj.Name, field))
                setPendingBindField(nil)
                applyStreamerOverlay()
                return
            end
        end

        setStreamerStatus("Nothing bindable under the cursor. Try again.")
    end)
end

S.describeInstancePath = describeInstancePath
S.dumpStreamerCandidates = dumpStreamerCandidates
S.normalizeImageId = normalizeImageId
S.parseHexColor = parseHexColor
S.refreshStreamerOverlay = refreshStreamerOverlay
S.restoreHiddenElements = restoreHiddenElements
S.setPendingBindField = setPendingBindField
S.setStreamerEnabled = setStreamerEnabled
S.setStreamerStatus = setStreamerStatus
S.toHexString = toHexString
end
    end)()
    module(S)
end

-- ===================================== src/config.lua =====================================
do
    local module = (function()
-- config.lua - JSON config persistence through the executor's file API, the
-- per-map store (waypoints, keep list, attack book, zones), named configs,
-- the map picker and the mode switch.
return function(S)
local CFG = S.CFG
local RT = S.RT
local SM = S.SM
local HZ = S.HZ
local NAV = S.NAV
local LD = S.LD
local ZN = S.ZN
local Workspace = S.Workspace
local heavyDebug = S.heavyDebug
local toHexString = S.toHexString
local parseHexColor = S.parseHexColor
local describeInstancePath = S.describeInstancePath
local renderPathMarkers = S.renderPathMarkers
local refreshLowDetail = S.refreshLowDetail
local serializeZones = S.serializeZones
local loadZones = S.loadZones
local invalidateAttackBook = S.invalidateAttackBook
local MAP_LABELS = S.MAP_LABELS
local SCRIPT_VERSION = S.SCRIPT_VERSION

local CONFIG_FILE = "DungeonAutofarm_config.json"
local HttpService = game:GetService("HttpService")

local function hasFileAccess()
    return type(writefile) == "function" and type(readfile) == "function" and type(isfile) == "function"
end
local function resolveInstancePath(path)
    local node = game
    for segment in string.gmatch(path, "[^%.]+") do
        if not (node == game and segment == "game") then
            local nextNode = node:FindFirstChild(segment)
            if not nextNode then return nil end
            node = nextNode
        end
    end
    return node ~= game and node or nil
end

-- ------------------------------------------------------------------ mode
local function setMode(mode)
    if mode ~= "legacy" and mode ~= "clone" then mode = "clone" end
    RT.mode = mode
    if S.setDodgeActive then S.setDodgeActive(mode == "clone") end
end

-- ------------------------------------------------------------------ per-map store
local function syncCurrentMapToStore()
    local waypath = {}
    for _, pos in ipairs(NAV.waypath) do waypath[#waypath + 1] = { x = pos.X, y = pos.Y, z = pos.Z } end
    local keep = {}
    for name in pairs(LD.keepNames) do keep[#keep + 1] = name end
    local book = {}
    for _, r in ipairs(HZ.attackBook) do book[#book + 1] = { name = r.name, enabled = r.enabled ~= false, hits = r.hits or 0, damage = r.damage or 0 } end
    RT.attackData[RT.currentMap] = book
    RT.zoneData[RT.currentMap] = serializeZones()
    RT.mapData[RT.currentMap] = { waypath = waypath, keep = keep }
end
local function applyMapFromStore(code)
    local entry = RT.mapData[code] or {}
    NAV.waypath = {}
    if type(entry.waypath) == "table" then
        for _, p in ipairs(entry.waypath) do
            if type(p) == "table" and tonumber(p.x) and tonumber(p.y) and tonumber(p.z) then
                NAV.waypath[#NAV.waypath + 1] = Vector3.new(p.x, p.y, p.z)
            end
        end
    end
    NAV.pathIndex = 1
    renderPathMarkers()
    if S.refreshPathPanel then S.refreshPathPanel() end
    LD.keepNames = {}
    if type(entry.keep) == "table" then
        for _, name in ipairs(entry.keep) do if type(name) == "string" then LD.keepNames[name] = true end end
    end
    refreshLowDetail()
    HZ.attackBook = {}
    for _, r in ipairs(RT.attackData[code] or {}) do
        if type(r) == "table" and type(r.name) == "string" then
            HZ.attackBook[#HZ.attackBook + 1] = { name = r.name, enabled = r.enabled ~= false, hits = tonumber(r.hits) or 0, damage = tonumber(r.damage) or 0 }
        end
    end
    invalidateAttackBook()
    loadZones(RT.zoneData[code])
    if S.refreshMapPanel then S.refreshMapPanel() end
    if S.refreshAttackBookPanel then S.refreshAttackBookPanel() end
    heavyDebug("Map", string.format("%s (%s): %d waypoint(s), %d attack(s), %d zone(s).", code, MAP_LABELS[code] or code, #NAV.waypath, #HZ.attackBook, #ZN.defs))
end
local function setCurrentMap(code)
    if not MAP_LABELS[code] then return end
    if code ~= RT.currentMap then
        syncCurrentMapToStore()
        RT.currentMap = code
    end
    applyMapFromStore(code)
end

-- ------------------------------------------------------------------ the table
-- Every CFG value with a plain type is saved by name; colours as hex.
local function buildConfigTable()
    local cfg = {}
    for key, default in pairs(RT.cfgDefaults) do
        local v = CFG[key]
        local t = typeof(v)
        if t == "number" or t == "boolean" or t == "string" then cfg[key] = v
        elseif t == "Color3" then cfg[key] = toHexString(v) end
    end
    local pinned = {}
    for name in pairs(RT.pinnedWindows) do pinned[#pinned + 1] = name end
    local binds = {}
    for obj, field in pairs(SM.manualBinds or {}) do
        if obj.Parent then binds[#binds + 1] = { path = describeInstancePath(obj), field = field } end
    end
    local own, learned = {}, {}
    for name in pairs(HZ.ownNames) do own[#own + 1] = name end
    for name in pairs(HZ.learnedNames) do learned[#learned + 1] = name end
    syncCurrentMapToStore()
    return {
        version = SCRIPT_VERSION,
        cfg = cfg,
        rt = {
            mode = RT.mode, autoQ = RT.autoQEnabled, autoE = RT.autoEEnabled,
            renderPath = RT.renderPathEnabled, renderHazards = RT.renderHazardsEnabled, renderHitbox = RT.renderHitboxEnabled,
            debugLevel = RT.debugLevel, pinnedWindows = pinned,
        },
        streamer = {
            enabled = SM.enabled, fields = SM.fields,
            vipColor = toHexString(SM.vipColor), levelColor = toHexString(SM.levelColor), borderColor = toHexString(SM.borderColor),
            avatarImage = SM.avatarImage, autoHideOverlays = SM.autoHideOverlays, binds = binds,
        },
        ownAttackNames = own,
        learnedTelegraphNames = learned,
        currentMap = RT.currentMap,
        maps = RT.mapData,
        attacksByMap = RT.attackData,
        zonesByMap = RT.zoneData,
    }
end

local function applyConfigData(data)
    if type(data.cfg) == "table" then
        for key, default in pairs(RT.cfgDefaults) do
            local v = data.cfg[key]
            local t = typeof(default)
            if v ~= nil then
                if t == "number" and tonumber(v) then CFG[key] = tonumber(v)
                elseif t == "boolean" then CFG[key] = v == true
                elseif t == "string" and type(v) == "string" then CFG[key] = v
                elseif t == "Color3" and type(v) == "string" then CFG[key] = parseHexColor(v) or default end
            end
        end
    elseif type(data.combat) == "table" then
        -- A 4.x file: keep what still means the same thing.
        local c = data.combat
        RT.autoQEnabled = c.autoQ == true
        RT.autoEEnabled = c.autoE == true
        CFG.abilityRadius = tonumber(c.abilityRadius) or CFG.abilityRadius
        CFG.attackRange = tonumber(c.attackRange) or CFG.attackRange
        if c.followPath ~= nil then CFG.followPath = c.followPath == true end
        if c.loopPath ~= nil then CFG.loopPath = c.loopPath == true end
        CFG.waypointClearRadius = tonumber(c.waypointClearRadius) or CFG.waypointClearRadius
        if c.mode == "legacy" or c.mode == "clone" then RT.mode = c.mode end
        if type(data.visuals) == "table" then
            local v = data.visuals
            CFG.guiBlur = tonumber(v.guiBlur) or CFG.guiBlur
            CFG.guiDim = tonumber(v.guiDim) or CFG.guiDim
            if type(v.menuKey) == "string" then CFG.menuKey = v.menuKey end
        end
    end
    local rt = data.rt
    if type(rt) == "table" then
        if rt.mode == "legacy" or rt.mode == "clone" then RT.mode = rt.mode end
        if rt.autoQ ~= nil then RT.autoQEnabled = rt.autoQ == true end
        if rt.autoE ~= nil then RT.autoEEnabled = rt.autoE == true end
        if rt.renderPath ~= nil then RT.renderPathEnabled = rt.renderPath == true end
        if rt.renderHazards ~= nil then RT.renderHazardsEnabled = rt.renderHazards == true end
        if rt.renderHitbox ~= nil then RT.renderHitboxEnabled = rt.renderHitbox == true end
        RT.debugLevel = tonumber(rt.debugLevel) or RT.debugLevel
        if type(rt.pinnedWindows) == "table" then
            RT.pinnedWindows = {}
            for _, name in ipairs(rt.pinnedWindows) do if type(name) == "string" then RT.pinnedWindows[name] = true end end
        end
    end
    local ok = pcall(function() return Enum.KeyCode[CFG.menuKey] end)
    if not ok then CFG.menuKey = RT.cfgDefaults.menuKey end
    setMode(RT.mode)

    local streamer = data.streamer
    if type(streamer) == "table" then
        if type(streamer.fields) == "table" then
            for key in pairs(SM.fields) do
                if type(streamer.fields[key]) == "string" then SM.fields[key] = streamer.fields[key] end
            end
        end
        SM.vipColor = parseHexColor(streamer.vipColor) or SM.vipColor
        SM.levelColor = parseHexColor(streamer.levelColor) or SM.levelColor
        SM.borderColor = parseHexColor(streamer.borderColor) or SM.borderColor
        if type(streamer.avatarImage) == "string" then SM.avatarImage = streamer.avatarImage end
        if streamer.autoHideOverlays ~= nil then SM.autoHideOverlays = streamer.autoHideOverlays == true end
        if type(streamer.binds) == "table" and SM.manualBinds then
            for _, bind in ipairs(streamer.binds) do
                if type(bind) == "table" and type(bind.path) == "string" then
                    local obj = resolveInstancePath(bind.path)
                    if obj then SM.manualBinds[obj] = bind.field end
                end
            end
        end
    end
    HZ.ownNames = {}
    for _, name in ipairs(type(data.ownAttackNames) == "table" and data.ownAttackNames or {}) do
        if type(name) == "string" then HZ.ownNames[string.lower(name)] = true end
    end
    HZ.learnedNames = {}
    for _, name in ipairs(type(data.learnedTelegraphNames) == "table" and data.learnedTelegraphNames or {}) do
        if type(name) == "string" then HZ.learnedNames[string.lower(name)] = true end
    end
    if type(data.maps) == "table" then RT.mapData = data.maps end
    if type(data.attacksByMap) == "table" then RT.attackData = data.attacksByMap end
    if type(data.zonesByMap) == "table" then RT.zoneData = data.zonesByMap end
    if type(data.currentMap) == "string" and MAP_LABELS[data.currentMap] then RT.currentMap = data.currentMap end
    applyMapFromStore(RT.currentMap)
    return streamer ~= nil and streamer.enabled == true
end

-- ------------------------------------------------------------------ files
local function saveConfig()
    if not hasFileAccess() then return false, "no file access in this executor" end
    local ok, err = pcall(function() writefile(CONFIG_FILE, HttpService:JSONEncode(buildConfigTable())) end)
    if ok then heavyDebug("Config", "Saved to " .. CONFIG_FILE) return true end
    heavyDebug("Config", "Save failed: " .. tostring(err))
    return false, tostring(err)
end
local function saveConfigStore()
    if not hasFileAccess() then return false, "no file access in this executor" end
    local ok, err = pcall(function() writefile(CFG.configFile, HttpService:JSONEncode({ version = SCRIPT_VERSION, configs = RT.configs })) end)
    if ok then return true end
    return false, tostring(err)
end
local function loadConfigStore()
    if not hasFileAccess() then return false end
    local exists = false
    pcall(function() exists = isfile(CFG.configFile) end)
    if not exists then return false end
    local data
    local ok = pcall(function() data = HttpService:JSONDecode(readfile(CFG.configFile)) end)
    if not ok or type(data) ~= "table" or type(data.configs) ~= "table" then return false end
    RT.configs = {}
    for _, entry in ipairs(data.configs) do
        if type(entry) == "table" and type(entry.name) == "string" and type(entry.data) == "table" then
            RT.configs[#RT.configs + 1] = { name = entry.name, savedAt = tonumber(entry.savedAt) or 0, data = entry.data }
        end
    end
    return true
end
local function saveNamedConfig(name)
    name = tostring(name):gsub("^%s+", ""):gsub("%s+$", "")
    if name == "" then return false, "give it a name" end
    local snapshot = { name = name, savedAt = os.time(), data = buildConfigTable() }
    local replaced = false
    for i, entry in ipairs(RT.configs) do
        if entry.name == name then RT.configs[i] = snapshot replaced = true break end
    end
    if not replaced then RT.configs[#RT.configs + 1] = snapshot end
    saveConfigStore()
    if S.refreshConfigPanel then S.refreshConfigPanel() end
    return true
end
local function loadNamedConfig(index)
    local entry = RT.configs[index]
    if not entry then return false end
    local wantsStreamer = applyConfigData(entry.data)
    if S.refreshAllWidgets then S.refreshAllWidgets() end
    if S.refreshPathPanel then S.refreshPathPanel() end
    if S.refreshMapPanel then S.refreshMapPanel() end
    if S.refreshAttackBookPanel then S.refreshAttackBookPanel() end
    return true, wantsStreamer
end
local function deleteNamedConfig(index)
    if not table.remove(RT.configs, index) then return false end
    saveConfigStore()
    if S.refreshConfigPanel then S.refreshConfigPanel() end
    return true
end
local function renameNamedConfig(index, name)
    local entry = RT.configs[index]
    if not entry then return false end
    name = tostring(name):gsub("^%s+", ""):gsub("%s+$", "")
    if name == "" then return false end
    entry.name = name
    saveConfigStore()
    if S.refreshConfigPanel then S.refreshConfigPanel() end
    return true
end
local function loadConfig()
    if not hasFileAccess() then return false, "no file access in this executor" end
    local exists = false
    pcall(function() exists = isfile(CONFIG_FILE) end)
    if not exists then return false, "no saved config yet" end
    local data
    local ok, err = pcall(function() data = HttpService:JSONDecode(readfile(CONFIG_FILE)) end)
    if not ok or type(data) ~= "table" then
        heavyDebug("Config", "Load failed: " .. tostring(err))
        return false, "config file unreadable"
    end
    local wantsStreamer = applyConfigData(data)
    loadConfigStore()
    heavyDebug("Config", "Loaded from " .. CONFIG_FILE)
    return true, wantsStreamer
end
local function syncStreamerToggleWidget()
    if SM.syncToggleWidget then pcall(SM.syncToggleWidget) end
end

-- ------------------------------------------------------------------ the game's map
local MAP_BY_GAME_NAME = {
    ["desert temple"] = "DT", ["winter outpost"] = "WO", ["pirate island"] = "PI",
    ["king's castle"] = "KC", ["the underworld"] = "TU", ["samurai palace"] = "SP",
    ["the canals"] = "TC", ["ghastly harbor"] = "GH", ["steampunk sewers"] = "SS",
    ["orbital outpost"] = "OO", ["volcanic chambers"] = "VC", ["aquatic temple"] = "AT",
    ["enchanted forest"] = "EF", ["northern lands"] = "NL",
}
local function applyDetectedMap(raw)
    if not CFG.autoDetectMap then return end
    local code = MAP_BY_GAME_NAME[string.lower(tostring(raw or ""))]
    if not code or code == RT.currentMap then return end
    setCurrentMap(code)
    heavyDebug("Map", string.format("The game says %s; switched to %s.", tostring(raw), code))
    if S.refreshAllWidgets then S.refreshAllWidgets() end
    if S.refreshZonePanel then S.refreshZonePanel() end
end
local function watchDungeonName()
    local value = Workspace:FindFirstChild("dungeonName")
    if not value or not value:IsA("StringValue") then return false end
    applyDetectedMap(value.Value)
    table.insert(RT.indexConnections, value.Changed:Connect(applyDetectedMap))
    return true
end

-- One button's worth of tuning: the dodge section back to how it shipped.
local function applyRecommendedDodge()
    for key, value in pairs(RT.cfgDefaults) do
        if string.sub(key, 1, 5) == "dodge" or key == "moveMode" or key == "moveSpeed" or key == "hitAfter"
            or key == "damageBrickClearance" or key == "preemptiveClearance" then
            CFG[key] = value
        end
    end
    heavyDebug("Dodge", "Dodge settings reset to the recommended tuning.")
end

S.loadConfig = loadConfig
S.saveConfig = saveConfig
S.applyRecommendedDodge = applyRecommendedDodge
S.setCurrentMap = setCurrentMap
S.watchDungeonName = watchDungeonName
S.applyDetectedMap = applyDetectedMap
S.saveNamedConfig = saveNamedConfig
S.loadNamedConfig = loadNamedConfig
S.deleteNamedConfig = deleteNamedConfig
S.renameNamedConfig = renameNamedConfig
S.loadConfigStore = loadConfigStore
S.setMode = setMode
S.syncCurrentMapToStore = syncCurrentMapToStore
S.syncStreamerToggleWidget = syncStreamerToggleWidget
end
    end)()
    module(S)
end

